"""Cost estimation and a hard spend cap for the paid agent tier.

The agent arm costs real money and its cost grows with repo size. To avoid
surprises we (1) estimate the full run from a cheap probe on the smallest slice,
print the projection, and (2) enforce a hard cumulative cap, skipping any run
that would push spend over the ceiling. Per-run caps are also passed to the CLI
via --max-budget-usd.
"""


class BudgetTracker:
    def __init__(self, cap_usd):
        self.cap = cap_usd
        self._spent = 0.0
        self.skipped = 0

    def spent(self):
        return self._spent

    def remaining(self):
        return max(0.0, self.cap - self._spent)

    def record(self, usd):
        if usd:
            self._spent += usd

    def can_afford(self, est_usd):
        return (self._spent + max(0.0, est_usd)) <= self.cap


def project(probe_usd, probe_loc, slice_locs, models, n):
    """Linear-in-LOC projection of total spend across slices x models x n runs.

    probe_usd is the measured cost of one agent run on a slice of probe_loc.
    Returns (per_slice_estimate, grand_total).
    """
    rate = (probe_usd / probe_loc) if probe_loc else 0.0
    per_slice = {loc: rate * loc for loc in slice_locs}
    grand_total = sum(per_slice.values()) * len(models) * n
    return per_slice, grand_total


def fmt_projection(per_slice, grand_total, models, n, cap):
    lines = ["Projected agent spend (linear-in-LOC from probe):"]
    for loc in sorted(per_slice):
        lines.append("  ~$%.3f per run at %d LOC" % (per_slice[loc], loc))
    lines.append("  x %d models x %d runs  =>  ~$%.2f total" % (len(models), n, grand_total))
    lines.append("  budget cap: $%.2f  (%s)" % (
        cap, "within cap" if grand_total <= cap else "OVER cap -- runs will stop at the ceiling"))
    return "\n".join(lines)

#!/usr/bin/env python3
"""Reconstruct granular PER-RUN agent telemetry from the clean-run transcripts.

The orchestrator only stores aggregates; for the paper we need each individual
run's tokens, wall time, cost, turns, recovered count and status. This parses the
most recent N agent transcripts per slice (N = models x runs of the clean run),
scores each against the slice ground truth, and prints a per-run table plus
per-cell means (to cross-check against the report) and cost projections.

Read-only. Usage: python3 granular.py
"""
import datetime
import glob
import json
import os
import re
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import paths            # noqa: E402
from systems import agent as A  # noqa: E402

PROJECTS = os.path.expanduser("~/.claude/projects")
AGENT_SLICES = {"microsoft_vscode-10k", "microsoft_vscode-100k", "microsoft_vscode-1m"}
RUNS_PER_SLICE = 6  # 3 models x 2 runs


def project_dir(slice_dir):
    return os.path.join(PROJECTS, re.sub(r"[/_.]", "-", os.path.realpath(slice_dir)))


def short(model):
    for k in ("haiku", "sonnet", "opus"):
        if k and k in (model or ""):
            return k
    return None


def parse(f):
    model = None
    tin = tout = cost = turns = 0
    ts = []
    final = None
    for line in open(f):
        try:
            e = json.loads(line)
        except json.JSONDecodeError:
            continue
        if e.get("timestamp"):
            ts.append(e["timestamp"])
        m = e.get("message", {})
        if not isinstance(m, dict):
            continue
        if m.get("model"):
            model = m["model"]
        mu = m.get("modelUsage") or {}
        for k in mu:
            if short(k):
                model = model or k
        for v in mu.values():
            if isinstance(v, dict):
                cost += v.get("costUSD") or 0
        u = m.get("usage") or {}
        if u:
            turns += 1
            tin += (u.get("input_tokens") or 0) + (u.get("cache_creation_input_tokens") or 0) \
                + (u.get("cache_read_input_tokens") or 0)
            tout += u.get("output_tokens") or 0
        c = m.get("content")
        if isinstance(c, list):
            for b in c:
                if isinstance(b, dict) and b.get("type") == "text" and '"pairs"' in str(b.get("text", "")):
                    final = b["text"]
    wall = None
    if len(ts) >= 2:
        try:
            t0 = datetime.datetime.fromisoformat(ts[0].replace("Z", "+00:00"))
            t1 = datetime.datetime.fromisoformat(ts[-1].replace("Z", "+00:00"))
            wall = (t1 - t0).total_seconds()
        except (ValueError, TypeError):
            wall = None
    return {"model": short(model), "tin": tin, "tout": tout, "cost": cost,
            "turns": turns, "wall": wall, "final": final}


def load_report_costs():
    """(model, host_loc) -> usd_mean from the clean-run report (real -p cost)."""
    rp = os.path.join(HERE, "..", "results", "2026-06-28-ts-final-claude.json")
    out = {}
    try:
        d = json.load(open(rp))
    except (OSError, json.JSONDecodeError):
        return out
    for r in d.get("agents", []):
        model = r["system"].split(":")[-1]
        out[(model, r["host_loc"])] = r.get("usd_mean")
    return out


def latest_per_model(pdir):
    """2 most recent transcripts per model = the clean run's 2 runs/model.

    Transcripts with wall > 1100s are dropped: the clean run capped every run at
    900s, so a longer one can only be from an older pre-timeout run leaking in.
    """
    parsed = []
    for f in glob.glob(pdir + "/*.jsonl"):
        p = parse(f)
        if p["model"] and not (p["wall"] and p["wall"] > 1100):
            p["_mtime"] = os.path.getmtime(f)
            parsed.append(p)
    by_model = {}
    for p in sorted(parsed, key=lambda x: x["_mtime"]):
        by_model.setdefault(p["model"], []).append(p)
    out = []
    for m, ps in by_model.items():
        out += ps[-2:]
    return out


def main():
    base = os.path.join(paths.data_dir(), "slices")
    meta = json.load(open(os.path.join(base, "slices.json")))
    slmap = {s["name"]: s for s in meta["slices"]}
    report_cost = load_report_costs()

    print("# Granular per-run agent telemetry (clean run, n=2)")
    print("# tokens & time per run are exact (from transcripts); $ is per-cell (from the -p cost accounting)\n")
    print("%-6s %-7s %-3s %10s %8s %6s %8s  %s" %
          ("slice", "model", "run", "tok_in", "tok_out", "turns", "wall_s", "found/status"))
    rows = []
    for name in sorted(AGENT_SLICES, key=lambda n: slmap[n]["host_loc"]):
        s = slmap[name]
        gt = json.load(open(s["gt_path"]))
        index = A._index(gt)
        total = len(gt["pairs"])
        pdir = project_dir(s["dir"])
        runs = sorted(latest_per_model(pdir), key=lambda x: (x["model"], x["_mtime"]))
        per_model = {}
        for p in runs:
            if p["final"]:
                pred, _ = A._extract_pairs({"result": p["final"]}, index)
                found = len({fr for fr in pred})
                status = "%d/%d" % (found, total)
            else:
                found = 0
                status = "DNF"
            ri = per_model.get(p["model"], 0)
            per_model[p["model"]] = ri + 1
            row = {"slice": name.split("-")[-1], "loc": s["host_loc"], "model": p["model"],
                   "run": ri, "tin": p["tin"], "tout": p["tout"], "cost": p["cost"],
                   "turns": p["turns"], "wall": p["wall"], "found": found, "status": status}
            rows.append(row)
            print("%-6s %-7s %-3d %10s %8s %6d %8s  %s" % (
                row["slice"], row["model"], row["run"], f"{p['tin']:,}", f"{p['tout']:,}",
                p["turns"], ("%.0f" % p["wall"]) if p["wall"] else "?", status))

    # per-cell means (cross-check vs report) + cost projections
    print("\n# Per-cell means (cross-check vs report)")
    cells = {}
    for r in rows:
        cells.setdefault((r["loc"], r["model"]), []).append(r)
    total_cost = 0.0
    for (loc, model), rs in sorted(cells.items()):
        comp = [r for r in rs if r["status"] != "DNF"]
        f_mean = sum(r["found"] for r in comp) / len(comp) if comp else 0
        c_mean = report_cost.get((model, loc)) or 0.0
        total_cost += c_mean * len(rs)
        ti_mean = sum(r["tin"] for r in rs) / len(rs)
        w = [r["wall"] for r in rs if r["wall"]]
        w_mean = sum(w) / len(w) if w else 0
        print("  %9s %-7s found_mean=%4.1f cost/run=$%.2f tok_in_mean=%12s wall_mean=%4.0fs (n=%d, dnf=%d)" % (
            f"{loc:,}", model, f_mean, c_mean, f"{ti_mean:,.0f}", w_mean, len(rs), len(rs) - len(comp)))

    total_tin = sum(r["tin"] for r in rows)
    print("\n# Totals: %d runs, ~$%.2f notional cost (Max subscription = $0 real), %s input tokens"
          % (len(rows), total_cost, f"{total_tin:,}"))
    # projection from the 1M cells: blended $/Mtok and cost to scan the full corpus
    big_locs = [(loc, model) for (loc, model) in cells if loc >= 1_000_000]
    big_tok = sum(r["tin"] for r in rows if r["loc"] >= 1_000_000)
    big_cost = sum((report_cost.get((m, loc)) or 0.0) * len([r for r in rows if r["loc"] == loc and r["model"] == m])
                   for (loc, m) in big_locs)
    n_big = len([r for r in rows if r["loc"] >= 1_000_000])
    if n_big:
        tpl = big_tok / n_big / 1_000_000 * 1000     # input tok per 1k LOC
        cpl = big_cost / n_big / 1_000_000 * 1000    # $ per 1k LOC (notional)
        full = meta["available_loc"]
        print("# Projection @1M: ~%s input tok / 1k LOC, ~$%.4f / 1k LOC (notional)" % (f"{tpl:,.0f}", cpl))
        print("# One agent pass over the full %s-LOC corpus: ~$%.2f notional (dupehound: $0, <2s)"
              % (f"{full:,}", cpl * full / 1000))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Reconstruct the scaling report from the agent transcripts already produced.

The live orchestrator only writes its result file at the very end; when a run is
killed (e.g. after a hung agent), we still want the honest partial picture. This
reads each completed agent session from the Claude transcripts, scores what it
actually reported against the realistic ground truth, re-runs dupehound fresh
(free) for the baseline, and writes the report -- marking any (model, slice)
cell with no completed run as DNF (did not finish), never as "found zero".
"""
import glob
import json
import os
import re
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import paths            # noqa: E402
import score            # noqa: E402
import run_scaling      # noqa: E402
from systems import agent as agent_sys      # noqa: E402
from systems import dupehound as dh_sys     # noqa: E402

PROJECTS = os.path.expanduser("~/.claude/projects")
WINDOW_S = 16 * 3600  # only this run's transcripts


def short_model(model_id):
    for k in ("haiku", "sonnet", "opus"):
        if k in (model_id or ""):
            return k
    return None


def parse_transcript(path):
    model = None
    tin = tout = cost = turns = 0
    final = None
    ts = []
    for line in open(path):
        try:
            e = json.loads(line)
        except json.JSONDecodeError:
            continue
        if e.get("timestamp"):
            ts.append(e["timestamp"])
        m = e.get("message", {})
        if not isinstance(m, dict):
            continue
        if m.get("model"):
            model = m["model"]
        u = m.get("usage") or {}
        if u:
            turns += 1
            tin += (u.get("input_tokens") or 0) + (u.get("cache_creation_input_tokens") or 0) \
                + (u.get("cache_read_input_tokens") or 0)
            tout += u.get("output_tokens") or 0
        mu = m.get("modelUsage") or {}
        for v in mu.values():
            if isinstance(v, dict):
                cost += v.get("costUSD") or 0
        c = m.get("content")
        if isinstance(c, list):
            for b in c:
                if isinstance(b, dict) and b.get("type") == "text" and '"pairs"' in str(b.get("text", "")):
                    final = b["text"]
    wall_ms = None
    if len(ts) >= 2:
        try:
            import datetime
            t0 = datetime.datetime.fromisoformat(ts[0].replace("Z", "+00:00"))
            t1 = datetime.datetime.fromisoformat(ts[-1].replace("Z", "+00:00"))
            wall_ms = (t1 - t0).total_seconds() * 1000.0
        except (ValueError, TypeError):
            wall_ms = None
    return {"model": short_model(model), "final": final, "tokens_in": tin,
            "tokens_out": tout, "usd": cost or None, "turns": turns, "wall_ms": wall_ms}


def slice_project_dir(slice_dir):
    # Claude Code keys its project dirs by the realpath with /, _ and . -> -
    key = re.sub(r"[/_.]", "-", os.path.realpath(slice_dir))
    return os.path.join(PROJECTS, key)


def main():
    base = os.path.join(paths.data_dir(), "slices")
    meta = json.load(open(os.path.join(base, "slices.json")))
    slices = sorted(meta["slices"], key=lambda s: s["host_loc"])
    now = time.time()
    models = ["haiku", "sonnet", "opus"]

    dh_rows, agent_rows, notes = [], [], []
    dh_version = None

    for s in slices:
        gt = json.load(open(s["gt_path"]))
        index = agent_sys._index(gt)

        # dupehound baseline (fresh, free)
        dh_runs = [dh_sys.run(s["dir"], gt, 0.80, 20) for _ in range(3)]
        dh_version = dh_runs[0]["system"]
        dh_rows.append(run_scaling.attach_size(score.aggregate(dh_runs, gt), s))

        # agent runs from transcripts
        pdir = slice_project_dir(s["dir"])
        by_model = {m: [] for m in models}
        for f in glob.glob(os.path.join(pdir, "*.jsonl")):
            if now - os.path.getmtime(f) > WINDOW_S:
                continue
            p = parse_transcript(f)
            if not p["model"] or p["model"] not in by_model:
                continue
            if not p["final"]:
                continue  # incomplete session -> not counted
            pred, _ = agent_sys._extract_pairs({"result": p["final"]}, index)
            by_model[p["model"]].append({
                "system": "claude-agent:%s" % p["model"], "kind": "agent",
                "simulated": False, "predicted_pairs": pred,
                "telemetry": {"wall_ms": p["wall_ms"], "tokens_in": p["tokens_in"],
                              "tokens_out": p["tokens_out"], "usd": p["usd"]},
            })
        for m in models:
            runs = by_model[m]
            if runs:
                agent_rows.append(run_scaling.attach_size(score.aggregate(runs, gt), s))
            else:
                notes.append("%s on %s: all runs hung/incomplete (DNF)" % (m, s["name"]))
                agent_rows.append(run_scaling.attach_size(_dnf_row("claude-agent:%s" % m, gt), s))

    rmeta = {
        "date": "2026-06-28", "tag": "ts-realistic", "repo": meta["repo"],
        "commit": meta["commit"], "seed": meta["seed"], "profile": meta.get("lang") and "realistic",
        "clone_type_counts": json.load(open(slices[0]["gt_path"])).get("clone_type_counts", {}),
        "slices": slices, "needle_functions": slices[0]["needle_functions"],
        "needle_pairs": slices[0]["needle_pairs"], "dupehound": dh_version,
        "models": models, "dh_runs": 3, "agent_runs": "2 (partial; reconstructed)",
        "spent": 0.0, "cap": 0.0, "notes": notes,
        "reconstructed": True,
    }
    out = os.path.join(HERE, "..", "results", "2026-06-28-ts-realistic")
    with open(os.path.abspath(out) + ".json", "w") as f:
        json.dump({"meta": run_scaling._meta_json(rmeta),
                   "dupehound": run_scaling._rows_json(dh_rows),
                   "agents": run_scaling._rows_json(agent_rows)}, f, indent=2)
    run_scaling.write_markdown(os.path.abspath(out) + ".md", rmeta, dh_rows, agent_rows)
    print("wrote", os.path.abspath(out) + ".md")
    for r in dh_rows + agent_rows:
        print("  %-22s %-9s tp=%.1f" % (r["system"], "{:,}".format(r["host_loc"]), r["tp_mean"]))


def _dnf_row(system, gt):
    return {
        "system": system, "kind": "agent", "simulated": False, "runs": 0,
        "f1_mean": None, "f1_std": 0.0, "recall_mean": 0.0, "recall_std": 0.0,
        "precision_mean": 0.0, "precision_std": 0.0, "mcc_mean": 0.0,
        "recall_by_type": {t: 0.0 for t in ("1", "2", "3", "4")},
        "tp_mean": 0.0, "fp_mean": 0.0, "fn_mean": float(len(gt["pairs"])),
        "wall_ms_mean": None, "wall_ms_std": 0.0,
        "tokens_in_mean": None, "tokens_out_mean": None,
        "usd_mean": None, "cost_per_tp": None, "determinism": None,
    }


if __name__ == "__main__":
    main()

"""OpenAI (and other OpenAI-compatible) autonomous-agent adapter.

Gives a chat model the SAME three read-only tools as the Claude arm -- glob,
grep, read_file -- all sandboxed to the slice directory, and asks it to find
duplicated functions on its own. Returns the same {predicted_pairs, telemetry}
contract as systems/agent.py, scored via the shared (file, function) index.

Isolation is by construction: the only tools are read-only file ops confined to
the slice dir, so the model cannot run dupehound, spawn sub-agents, or read the
ground truth (which lives outside the scanned dir). The OPENAI_API_KEY is read
from the environment only.
"""
import glob as globmod
import json
import os
import subprocess
import time

from systems.agent import PROMPT, _index, _extract_pairs

# USD per 1M tokens (input, output). Best-effort; edit to the provider's current
# published prices for citable cost. Token counts are always exact (from usage).
PRICES = {
    "gpt-5.5":       (1.25, 10.0),
    "gpt-5.4-mini":  (0.25, 2.0),
    "gpt-5-mini":    (0.25, 2.0),
}

MAX_READ_CHARS = 30000
MAX_GREP_LINES = 120
MAX_GLOB = 200

TOOLS = [
    {"type": "function", "function": {
        "name": "glob", "description": "List files matching a glob pattern (e.g. '**/*.ts').",
        "parameters": {"type": "object", "properties": {
            "pattern": {"type": "string"}}, "required": ["pattern"]}}},
    {"type": "function", "function": {
        "name": "grep", "description": "Search file contents with a regex; returns file:line matches.",
        "parameters": {"type": "object", "properties": {
            "pattern": {"type": "string"},
            "glob": {"type": "string", "description": "optional file glob filter, e.g. '*.ts'"}},
            "required": ["pattern"]}}},
    {"type": "function", "function": {
        "name": "read_file", "description": "Read a UTF-8 text file (truncated if large).",
        "parameters": {"type": "object", "properties": {
            "path": {"type": "string"}}, "required": ["path"]}}},
]


def _safe(root, path):
    full = os.path.realpath(os.path.join(root, path))
    return full if full.startswith(os.path.realpath(root) + os.sep) else None


def _tool_glob(root, pattern):
    hits = globmod.glob(os.path.join(root, pattern), recursive=True)
    rels = sorted(os.path.relpath(h, root) for h in hits if os.path.isfile(h))
    extra = len(rels) - MAX_GLOB
    out = "\n".join(rels[:MAX_GLOB])
    return out + ("\n... (%d more)" % extra if extra > 0 else "") or "(no matches)"


def _tool_grep(root, pattern, gl=None):
    cmd = ["grep", "-rIn", "--include", gl or "*.ts", "-e", pattern, root]
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
    except (subprocess.TimeoutExpired, OSError):
        return "(grep error/timeout)"
    lines = [ln.replace(root + os.sep, "") for ln in p.stdout.splitlines()]
    extra = len(lines) - MAX_GREP_LINES
    out = "\n".join(lines[:MAX_GREP_LINES])
    return out + ("\n... (%d more matches)" % extra if extra > 0 else "") or "(no matches)"


def _tool_read(root, path):
    full = _safe(root, path)
    if not full or not os.path.isfile(full):
        return "(no such file)"
    try:
        with open(full, encoding="utf-8") as f:
            data = f.read(MAX_READ_CHARS + 1)
    except (UnicodeDecodeError, OSError):
        return "(unreadable)"
    return data[:MAX_READ_CHARS] + ("\n... (truncated)" if len(data) > MAX_READ_CHARS else "")


def _dispatch(root, name, args):
    if name == "glob":
        return _tool_glob(root, args.get("pattern", ""))
    if name == "grep":
        return _tool_grep(root, args.get("pattern", ""), args.get("glob"))
    if name == "read_file":
        return _tool_read(root, args.get("path", ""))
    return "(unknown tool)"


def run(slice_dir, gt, model="gpt-5.5", run_idx=0, max_iters=40, timeout_s=900,
        base_url=None):
    try:
        from openai import OpenAI
    except ImportError:
        return _empty(model, "openai SDK not installed")
    if not os.environ.get("OPENAI_API_KEY"):
        return _empty(model, "OPENAI_API_KEY not set")

    client = OpenAI(base_url=base_url) if base_url else OpenAI()
    index = _index(gt)
    messages = [
        {"role": "system", "content": PROMPT},
        {"role": "user", "content": "The repository root is the current directory. "
         "Use the glob, grep and read_file tools to explore it and find duplicated "
         "functions. Paths are relative to the root."},
    ]
    tin = tout = 0
    final_text = ""
    t0 = time.perf_counter()
    err = None
    for _ in range(max_iters):
        if time.perf_counter() - t0 > timeout_s:
            err = "timed out after %ds" % timeout_s
            break
        try:
            resp = client.chat.completions.create(
                model=model, messages=messages, tools=TOOLS, tool_choice="auto")
        except Exception as e:  # noqa: BLE001
            err = "api error: %s" % repr(e)[:200]
            break
        u = getattr(resp, "usage", None)
        if u:
            tin += u.prompt_tokens or 0
            tout += u.completion_tokens or 0
        msg = resp.choices[0].message
        if not msg.tool_calls:
            final_text = msg.content or ""
            break
        messages.append({"role": "assistant", "content": msg.content,
                         "tool_calls": [tc.model_dump() for tc in msg.tool_calls]})
        for tc in msg.tool_calls:
            try:
                args = json.loads(tc.function.arguments or "{}")
            except json.JSONDecodeError:
                args = {}
            result = _dispatch(slice_dir, tc.function.name, args)
            messages.append({"role": "tool", "tool_call_id": tc.id, "content": result})
    wall_ms = (time.perf_counter() - t0) * 1000.0
    if not final_text and not err:
        err = "did not finish (max_iters)"

    predicted, reported = _extract_pairs({"result": final_text}, index)
    price = PRICES.get(model)
    usd = (tin / 1e6 * price[0] + tout / 1e6 * price[1]) if price else None
    out = {
        "system": "openai-agent:%s" % model, "kind": "agent",
        "predicted_pairs": predicted,
        "telemetry": {"wall_ms": wall_ms, "tokens_in": tin, "tokens_out": tout,
                      "usd": usd, "pairs_reported": reported},
        "config": {"model": model, "run_idx": run_idx, "max_iters": max_iters},
    }
    if err and not predicted:
        out["error"] = err
    return out


def _empty(model, error, wall_ms=0.0):
    return {"system": "openai-agent:%s" % model, "kind": "agent",
            "predicted_pairs": set(),
            "telemetry": {"wall_ms": wall_ms, "tokens_in": None, "tokens_out": None,
                          "usd": None, "pairs_reported": 0},
            "config": {"model": model}, "error": error}

"""dupehound system adapter for the benchmark.

Runs the dupehound binary over a planted corpus, maps every reported cluster
member back to a ground-truth function, and expands clusters into predicted
clone pairs. Telemetry: wall-clock measured here; tokens and cost are zero by
construction (local, deterministic CPU work).
"""
import json
import os
import subprocess
import time


def _bin():
    env = os.environ.get("DUPEHOUND_BIN")
    if env:
        return env
    here = os.path.dirname(__file__)
    return os.path.abspath(os.path.join(here, "..", "..", "..", "target", "release", "dupehound"))


def _version(binpath):
    try:
        out = subprocess.run([binpath, "--version"], capture_output=True, text=True)
        return out.stdout.strip() or "dupehound"
    except Exception:
        return "dupehound"


def _index_ground_truth(gt):
    """(basename, function name) -> func_id.

    Keyed by basename + function name: needle files may also contain sub-threshold
    filler, so we identify the planted function by name rather than assuming one
    function per file. dupehound reports paths relative to its scan root while
    ground truth records them relative to the corpus root, so basename is used.
    """
    return {(os.path.basename(fn["file"]), fn["name"]): fn["id"]
            for fn in gt["functions"]}


def _match(index, member):
    """Map a reported member to a ground-truth function id by (basename, name)."""
    return index.get((os.path.basename(member["file"]), member["name"]))


def run(corpus_dir, gt, threshold=0.80, min_tokens=20):
    binpath = _bin()
    by_file = _index_ground_truth(gt)

    t0 = time.perf_counter()
    proc = subprocess.run(
        [binpath, "scan", corpus_dir, "--json",
         "--threshold", str(threshold),
         "--min-tokens", str(min_tokens),
         "--include-tests"],
        capture_output=True, text=True,
    )
    elapsed_ms = (time.perf_counter() - t0) * 1000.0
    if proc.returncode != 0:
        raise RuntimeError("dupehound failed: %s" % proc.stderr[:500])
    report = json.loads(proc.stdout)

    predicted = set()
    for cluster in report.get("clusters", []):
        ids = []
        for m in cluster["members"]:
            fid = _match(by_file, m)
            if fid is not None:
                ids.append(fid)
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                if ids[i] != ids[j]:
                    predicted.add(frozenset((ids[i], ids[j])))

    return {
        "system": _version(binpath),
        "kind": "deterministic",
        "predicted_pairs": predicted,
        "telemetry": {
            "wall_ms": elapsed_ms,
            "self_reported_ms": report.get("stats", {}).get("elapsed_ms"),
            "tokens_in": 0,
            "tokens_out": 0,
            "usd": 0.0,
            "functions_seen": report.get("stats", {}).get("functions"),
        },
        "config": {"threshold": threshold, "min_tokens": min_tokens},
    }

