//! Groups matching pairs into duplicate clusters with union-find, picks a
//! representative per cluster, and suppresses nested matches: a function
//! paired with its own inner function, and an inner closure duplicated only
//! because its whole enclosing function is duplicated.

use crate::extract::FunctionUnit;
use crate::index::{Pair, similarity};

pub struct Member {
    pub func: u32,
    /// Similarity to the cluster representative (1.0 for the rep itself).
    pub similarity: f64,
}

pub struct Cluster {
    /// Representative (most significant lines) first.
    pub members: Vec<Member>,
    /// Lines you could delete by keeping only the representative.
    pub deletable_lines: u32,
    /// True when every member is test code.
    pub test_only: bool,
    /// True when every member's name is required to match its siblings by
    /// construction — a Rust trait-impl method (`From`, `Display`, ...) or a
    /// Clojure `defmethod` dispatch branch. Like `test_only`, these are kept
    /// out of the slop score: each is a distinct, required implementation,
    /// not deletable duplication.
    pub trait_impl_only: bool,
}

struct UnionFind {
    parent: Vec<u32>,
}

impl UnionFind {
    fn new(n: usize) -> Self {
        UnionFind {
            parent: (0..n as u32).collect(),
        }
    }
    fn find(&mut self, x: u32) -> u32 {
        let mut root = x;
        while self.parent[root as usize] != root {
            root = self.parent[root as usize];
        }
        let mut cur = x;
        while self.parent[cur as usize] != root {
            let next = self.parent[cur as usize];
            self.parent[cur as usize] = root;
            cur = next;
        }
        root
    }
    fn union(&mut self, a: u32, b: u32) {
        let (ra, rb) = (self.find(a), self.find(b));
        if ra != rb {
            self.parent[ra as usize] = rb;
        }
    }
}

pub fn build_clusters(functions: &[FunctionUnit], pairs: &[Pair]) -> Vec<Cluster> {
    let mut uf = UnionFind::new(functions.len());
    for p in pairs {
        uf.union(p.a, p.b);
    }

    let mut groups: rustc_hash::FxHashMap<u32, Vec<u32>> = rustc_hash::FxHashMap::default();
    for p in pairs {
        let root = uf.find(p.a);
        let g = groups.entry(root).or_default();
        for id in [p.a, p.b] {
            if !g.contains(&id) {
                g.push(id);
            }
        }
    }

    let mut clusters: Vec<Cluster> = groups
        .into_values()
        .filter_map(|mut ids| {
            drop_nested_members(functions, &mut ids);
            if ids.len() < 2 {
                return None;
            }
            // Representative = the member with the most significant lines;
            // the "original" is exempt from the deletable count.
            ids.sort_by_key(|&id| {
                let f = &functions[id as usize];
                (std::cmp::Reverse(f.sig_lines), f.file, f.start_line)
            });
            let rep = ids[0];
            let members: Vec<Member> = ids
                .iter()
                .map(|&id| Member {
                    func: id,
                    similarity: if id == rep {
                        1.0
                    } else {
                        similarity(&functions[id as usize], &functions[rep as usize])
                    },
                })
                .collect();
            let deletable_lines = ids[1..]
                .iter()
                .map(|&id| functions[id as usize].sig_lines)
                .sum();
            let test_only = ids.iter().all(|&id| functions[id as usize].is_test);
            let trait_impl_only = ids
                .iter()
                .all(|&id| functions[id as usize].is_trait_impl_method);
            Some(Cluster {
                members,
                deletable_lines,
                test_only,
                trait_impl_only,
            })
        })
        .collect();

    suppress_nested(functions, &mut clusters);
    clusters.sort_by_key(|c| std::cmp::Reverse(c.deletable_lines));
    clusters
}

/// True when `inner` sits strictly inside `outer` in the same file.
fn contains(outer: &FunctionUnit, inner: &FunctionUnit) -> bool {
    outer.file == inner.file
        && outer.start_byte <= inner.start_byte
        && inner.end_byte <= outer.end_byte
        && (outer.start_byte, outer.end_byte) != (inner.start_byte, inner.end_byte)
}

/// Drop a member that sits inside another member of the same cluster. A
/// function whose body is mostly one inner function (a Python factory, a
/// Clojure `defn` returning an `fn`) matches that inner function, but the
/// two are one piece of code, not a duplicate to delete.
fn drop_nested_members(functions: &[FunctionUnit], ids: &mut Vec<u32>) {
    let snapshot = ids.clone();
    ids.retain(|&id| {
        let inner = &functions[id as usize];
        !snapshot
            .iter()
            .any(|&o| o != id && contains(&functions[o as usize], inner))
    });
}

/// Drop a cluster when each of its members sits inside a member of one other
/// cluster — that's an inner function matching only because its enclosing
/// function is itself duplicated, and counting both double-counts the lines.
fn suppress_nested(functions: &[FunctionUnit], clusters: &mut Vec<Cluster>) {
    let snapshot: Vec<Vec<u32>> = clusters
        .iter()
        .map(|c| c.members.iter().map(|m| m.func).collect())
        .collect();
    let mut keep = vec![true; clusters.len()];
    for (i, members) in snapshot.iter().enumerate() {
        'outer_cluster: for (j, outer_members) in snapshot.iter().enumerate() {
            if i == j {
                continue;
            }
            for &m in members {
                let inner = &functions[m as usize];
                let nested = outer_members
                    .iter()
                    .any(|&o| contains(&functions[o as usize], inner));
                if !nested {
                    continue 'outer_cluster;
                }
            }
            keep[i] = false;
            break;
        }
    }
    let mut idx = 0;
    clusters.retain(|_| {
        let k = keep[idx];
        idx += 1;
        k
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lang::Lang;

    fn unit(
        file: u32,
        lines: (u32, u32),
        bytes: (u32, u32),
        sig: u32,
        fps: Vec<u64>,
    ) -> FunctionUnit {
        FunctionUnit {
            file,
            lang: Lang::Typescript,
            name: "f".into(),
            start_line: lines.0,
            end_line: lines.1,
            start_byte: bytes.0,
            end_byte: bytes.1,
            sig_lines: sig,
            fingerprints: fps,
            is_test: false,
            is_trait_impl_method: false,
        }
    }

    #[test]
    fn pairs_merge_into_one_cluster_with_largest_as_rep() {
        let functions = vec![
            unit(0, (1, 10), (0, 100), 9, vec![1, 2, 3]),
            unit(1, (1, 12), (0, 120), 11, vec![1, 2, 3]),
            unit(2, (1, 10), (0, 100), 9, vec![1, 2, 3]),
        ];
        let pairs = vec![Pair { a: 0, b: 1 }, Pair { a: 1, b: 2 }];
        let clusters = build_clusters(&functions, &pairs);
        assert_eq!(clusters.len(), 1);
        assert_eq!(clusters[0].members.len(), 3);
        assert_eq!(clusters[0].members[0].func, 1); // largest is rep
        assert_eq!(clusters[0].deletable_lines, 18);
    }

    #[test]
    fn nested_cluster_is_suppressed() {
        // Outer functions 0 and 1 duplicate each other; inner functions
        // 2-in-0 and 3-in-1 also "duplicate" — but only because their
        // parents do.
        let functions = vec![
            unit(0, (1, 30), (0, 900), 28, vec![1, 2, 3, 4]),
            unit(1, (1, 30), (0, 900), 28, vec![1, 2, 3, 4]),
            unit(0, (5, 12), (100, 400), 7, vec![2, 3]),
            unit(1, (5, 12), (100, 400), 7, vec![2, 3]),
        ];
        let pairs = vec![Pair { a: 0, b: 1 }, Pair { a: 2, b: 3 }];
        let clusters = build_clusters(&functions, &pairs);
        assert_eq!(clusters.len(), 1);
        assert_eq!(clusters[0].members.len(), 2);
        assert_eq!(clusters[0].deletable_lines, 28);
    }

    #[test]
    fn function_is_not_a_duplicate_of_its_own_inner_function() {
        // 0 is a factory whose body is mostly the inner function 1; they
        // fingerprint alike but are one piece of code.
        let functions = vec![
            unit(0, (1, 12), (0, 300), 10, vec![1, 2, 3, 4]),
            unit(0, (3, 10), (50, 250), 7, vec![1, 2, 3]),
        ];
        let pairs = vec![Pair { a: 0, b: 1 }];
        let clusters = build_clusters(&functions, &pairs);
        assert!(clusters.is_empty());
    }

    #[test]
    fn inner_function_is_dropped_but_real_duplicate_stays() {
        // 0 contains 1; 2 in another file is a real copy of 0. The cluster
        // keeps 0 and 2 and drops the inner 1.
        let functions = vec![
            unit(0, (1, 12), (0, 300), 10, vec![1, 2, 3, 4]),
            unit(0, (3, 10), (50, 250), 7, vec![1, 2, 3]),
            unit(1, (1, 12), (0, 300), 10, vec![1, 2, 3, 4]),
        ];
        let pairs = vec![Pair { a: 0, b: 1 }, Pair { a: 1, b: 2 }];
        let clusters = build_clusters(&functions, &pairs);
        assert_eq!(clusters.len(), 1);
        let members: Vec<u32> = clusters[0].members.iter().map(|m| m.func).collect();
        assert_eq!(members, vec![0, 2]);
        assert_eq!(clusters[0].deletable_lines, 10);
    }
}

use crate::cli::CommonArgs;

/// Winnowing parameters. k-gram size and window size give the guarantee
/// threshold t = w + k - 1: any shared run of >= t normalized tokens is
/// always caught by at least one shared fingerprint.
pub const KGRAM: usize = 10;
pub const WINDOW: usize = 8;

pub const DEFAULT_SCAN_THRESHOLD: f64 = 0.80;
pub const DEFAULT_CHECK_THRESHOLD: f64 = 0.85;

/// Minimum raw shared fingerprints before we bother computing exact Jaccard.
pub const MIN_SHARED_PREFILTER: u32 = 3;

/// How much of the smaller function must be covered by the larger one for the
/// experimental `--containment` track to report it. Stricter than the Jaccard
/// threshold on purpose: containment ignores the larger body, so a loose bar
/// here would flag any small function that happens to share a few fingerprints.
pub const DEFAULT_CONTAINMENT_THRESHOLD: f64 = 0.90;

/// Files larger than this are skipped (almost certainly generated/minified).
pub const MAX_FILE_BYTES: u64 = 2 * 1024 * 1024;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum TestPolicy {
    /// Scan test files, flag them, exclude test-only clusters from the score.
    FlagOnly,
    /// Treat test files like any other code.
    Include,
    /// Don't scan test files at all.
    Skip,
}

#[derive(Clone)]
pub struct Config {
    pub threshold: f64,
    pub min_tokens: usize,
    pub excludes: Vec<String>,
    pub default_excludes: bool,
    pub tests: TestPolicy,
    pub json: bool,
    /// Experimental: also run the C# "class shape" track (scan only).
    pub include_classes: bool,
    /// Experimental: also report small functions copied into larger ones
    /// (scan only), which Jaccard alone misses.
    pub containment: bool,
}

impl Config {
    pub fn from_common(common: &CommonArgs, default_threshold: f64) -> Self {
        let tests = if common.include_tests {
            TestPolicy::Include
        } else if common.exclude_tests {
            TestPolicy::Skip
        } else {
            TestPolicy::FlagOnly
        };
        Config {
            threshold: common
                .threshold
                .unwrap_or(default_threshold)
                .clamp(0.0, 1.0),
            min_tokens: common.min_tokens,
            excludes: common.excludes.clone(),
            default_excludes: !common.no_default_excludes,
            tests,
            json: common.json,
            include_classes: false,
            containment: false,
        }
    }
}

//! Parse a source file, extract function units via the language's query,
//! and fingerprint each function body.

use crate::config::{KGRAM, WINDOW};
use crate::fingerprint::winnow;
use crate::lang::Lang;
use crate::normalize::{normalize, significant_lines};
use rustc_hash::FxHasher;
use std::cell::RefCell;
use std::hash::{Hash, Hasher};
use streaming_iterator::StreamingIterator;
use tree_sitter::{Node, Parser, QueryCursor};

/// One function (or method) found in a file. The unit of duplicate
/// comparison is the *body*, so signatures, imports and license headers
/// never participate in matches.
#[derive(Clone)]
pub struct FunctionUnit {
    pub file: u32,
    pub lang: Lang,
    pub name: String,
    /// 1-based, spanning the whole function node (for reporting).
    pub start_line: u32,
    pub end_line: u32,
    /// Byte range of the whole function node (for --explain output).
    pub start_byte: u32,
    pub end_byte: u32,
    /// Significant lines in the body.
    pub sig_lines: u32,
    /// Sorted, distinct winnowing fingerprints of the body.
    pub fingerprints: Vec<u64>,
    pub is_test: bool,
    /// A method whose name is shared with its near-duplicate siblings by
    /// construction, so the sharing is required rather than accidental and
    /// the cluster can't be merged away: a Rust method inside an `impl
    /// Trait for Type` block (every impl of the same trait shares the
    /// method name — `from`, `fmt`, ...), a Clojure `defmethod` dispatch
    /// branch (every branch of the same multimethod shares its name), or a
    /// Java method annotated `@Override` (every implementation of the same
    /// interface/superclass method shares its name and is required by the
    /// contract, e.g. `equals`/`hashCode`/`toString`).
    pub is_trait_impl_method: bool,
}

pub struct FileAnalysis {
    pub functions: Vec<FunctionUnit>,
    pub sig_lines: u32,
    pub total_lines: u32,
}

thread_local! {
    static PARSER: RefCell<Parser> = RefCell::new(Parser::new());
}

/// Byte offset of the first `#[cfg(test)]` attribute whose next item is a
/// `mod` declaration, if any.
fn cfg_test_mod_offset(src: &str) -> Option<u32> {
    let mut from = 0;
    while let Some(pos) = src[from..].find("#[cfg(test)]") {
        let at = from + pos;
        let rest = src[at + "#[cfg(test)]".len()..].trim_start();
        let rest = rest.strip_prefix("pub ").unwrap_or(rest);
        if rest.starts_with("mod ") || rest.starts_with("mod\t") {
            // Only an inline module body (`mod tests { ... }`) hosts test
            // functions here; `mod tests;` lives in its own file.
            let inline = rest
                .find(['{', ';'])
                .is_some_and(|i| rest.as_bytes()[i] == b'{');
            if inline {
                return Some(at as u32);
            }
        }
        from = at + "#[cfg(test)]".len();
    }
    None
}

/// True if `func` is a method inside a trait implementation
/// (`impl SomeTrait for SomeType { ... }`). Such methods share their name with
/// every other impl of the same trait (`from`, `fmt`, `cmp`, ...) by
/// definition, so dupehound clusters them as look-alikes even though each is a
/// distinct, required implementation that cannot be merged away. Inherent
/// impls (`impl Type { ... }`) have no `trait` field and are not flagged.
fn is_rust_trait_impl_method(func: Node) -> bool {
    let Some(decl_list) = func.parent() else {
        return false;
    };
    if decl_list.kind() != "declaration_list" {
        return false;
    }
    let Some(impl_item) = decl_list.parent() else {
        return false;
    };
    impl_item.kind() == "impl_item" && impl_item.child_by_field_name("trait").is_some()
}

/// True if `func` (a Java `method_declaration`) carries an `@Override`
/// annotation. Every override of the same interface/superclass method
/// shares its name by construction — `equals`, `hashCode`, `toString`,
/// visitor dispatch methods, ... — so near-duplicate overrides across
/// unrelated classes can't be merged away. Same reasoning as
/// `is_rust_trait_impl_method`, reusing the same flag rather than inventing
/// a Java-specific one.
fn is_java_override_method(func: Node, src: &str) -> bool {
    let Some(modifiers) = func.child(0).filter(|c| c.kind() == "modifiers") else {
        return false;
    };
    let mut cursor = modifiers.walk();
    modifiers.children(&mut cursor).any(|m| {
        matches!(m.kind(), "marker_annotation" | "annotation")
            && m.child_by_field_name("name")
                .and_then(|n| n.utf8_text(src.as_bytes()).ok())
                == Some("Override")
    })
}

/// The text of `list`'s head symbol, if its first value child is a plain
/// symbol — the macro/function name a Clojure list form starts with, e.g.
/// "defmethod" or "defrecord".
fn clojure_list_head_text<'a>(list: Node, src: &'a str) -> Option<&'a str> {
    let head = list.child_by_field_name("value")?;
    if head.kind() != "sym_lit" {
        return None;
    }
    head.child_by_field_name("name")?
        .utf8_text(src.as_bytes())
        .ok()
}

/// True if `func` is a Clojure `defmethod` form. Every defmethod for the
/// same multimethod shares its `.name` (the multimethod name) by
/// construction — one form per dispatch value — so near-duplicate dispatch
/// branches can't be merged away. Same situation as `is_rust_trait_impl_method`
/// above, reusing the same flag rather than inventing a Clojure-specific one.
fn is_clojure_defmethod(func: Node, src: &str) -> bool {
    clojure_list_head_text(func, src) == Some("defmethod")
}

/// True if `func`'s immediate parent is a defrecord/deftype/extend-type/
/// extend-protocol/reify form -- a protocol method implementation, whose
/// name is shared with every other type's implementation of the same
/// method by construction. Same reasoning as `is_rust_trait_impl_method`
/// and `is_clojure_defmethod`: reuses `is_trait_impl_method` rather than a
/// third flag.
fn is_clojure_protocol_method(func: Node, src: &str) -> bool {
    let Some(parent) = func.parent() else {
        return false;
    };
    if parent.kind() != "list_lit" {
        return false;
    }
    matches!(
        clojure_list_head_text(parent, src),
        Some("defrecord" | "deftype" | "extend-type" | "extend-protocol" | "reify")
    )
}

/// Extract and fingerprint every function in `src`. `file` is the caller's
/// file id, stamped on each unit. `file_is_test` marks all units as test
/// code; Rust additionally marks functions inside `#[cfg(test)]` regions.
pub fn analyze_source(
    file: u32,
    lang: Lang,
    src: &str,
    min_tokens: usize,
    file_is_test: bool,
) -> Option<FileAnalysis> {
    let tree = PARSER.with(|p| {
        let mut parser = p.borrow_mut();
        parser.set_language(&lang.language()).ok()?;
        parser.parse(src, None)
    })?;
    let root = tree.root_node();

    // Cheap heuristic for Rust unit-test modules: everything at or after a
    // `#[cfg(test)]` that introduces a `mod` is the test module at the file
    // tail. (A bare `#[cfg(test)] use ...` near the top must NOT count.)
    let test_boundary = if lang == Lang::Rust && !file_is_test {
        cfg_test_mod_offset(src)
    } else {
        None
    };

    let query = lang.query();
    let name_idx = query.capture_index_for_name("name");
    let body_idx = query.capture_index_for_name("body");
    let func_idx = query.capture_index_for_name("func");

    // Body span alongside each unit, for dedup below -- a query can have
    // patterns whose @func spans legitimately differ while @body is the
    // same node (def+fn's @func is the whole `def` form, but its @body is
    // just the inner `(fn ...)`, which the generic bare-fn pattern also
    // matches on its own with @func == @body). Body span is what actually
    // gets fingerprinted, so it's the right identity for "is this the same
    // unit reported twice."
    let mut functions: Vec<(FunctionUnit, u32, u32)> = Vec::new();
    let mut cursor = QueryCursor::new();
    let mut matches = cursor.matches(query, root, src.as_bytes());
    while let Some(m) = matches.next() {
        let mut name = None;
        let mut body = None;
        let mut func = None;
        for cap in m.captures {
            if Some(cap.index) == name_idx {
                name = Some(cap.node);
            } else if Some(cap.index) == body_idx {
                body = Some(cap.node);
            } else if Some(cap.index) == func_idx {
                func = Some(cap.node);
            }
        }
        let (Some(body), Some(func)) = (body, func) else {
            continue;
        };
        let normalized = normalize(body, src.as_bytes());
        if normalized.codes.len() < min_tokens {
            continue;
        }
        let fingerprints = winnow(&normalized.codes, KGRAM, WINDOW);
        if fingerprints.is_empty() {
            continue;
        }
        let name = name
            .and_then(|n| n.utf8_text(src.as_bytes()).ok())
            .unwrap_or("<anonymous>")
            .to_string();
        let is_test = file_is_test || test_boundary.is_some_and(|b| func.start_byte() as u32 >= b);
        let is_trait_impl_method = match lang {
            Lang::Rust => is_rust_trait_impl_method(func),
            Lang::Clojure => {
                is_clojure_defmethod(func, src) || is_clojure_protocol_method(func, src)
            }
            Lang::Java => is_java_override_method(func, src),
            _ => false,
        };
        functions.push((
            FunctionUnit {
                file,
                lang,
                name,
                start_line: func.start_position().row as u32 + 1,
                end_line: func.end_position().row as u32 + 1,
                start_byte: func.start_byte() as u32,
                end_byte: func.end_byte() as u32,
                sig_lines: normalized.sig_lines,
                fingerprints,
                is_test,
                is_trait_impl_method,
            },
            body.start_byte() as u32,
            body.end_byte() as u32,
        ));
    }

    // Dedup on identical body span, preferring the named match over
    // "<anonymous>" when both exist for the same node (see the comment on
    // `functions` above). For every other language, where spans never
    // overlap, this is a no-op stable sort into source order.
    functions.sort_by_key(|(f, bs, be)| (*bs, *be, f.name == "<anonymous>"));
    functions.dedup_by(|(_, bs1, be1), (_, bs2, be2)| bs1 == bs2 && be1 == be2);
    let functions = functions.into_iter().map(|(f, ..)| f).collect();

    Some(FileAnalysis {
        functions,
        sig_lines: significant_lines(root),
        total_lines: src.lines().count() as u32,
    })
}

// ---------------------------------------------------------------------------
// Experimental "class shape" extraction (opt-in via `--include-classes`).
//
// Instead of fingerprinting a function body, this treats a *type* as a set of
// member signatures: each property/field/method signature (bodies dropped,
// identifiers KEPT) is hashed, and the class's "fingerprints" are that set.
// Two classes then cluster when they share most member signatures — which is
// the "near-duplicate model class" smell. This is a separate track from the
// function-body pipeline and never feeds the slop score.
// ---------------------------------------------------------------------------

/// Sub-nodes that mark the start of a member's *body* (dropped from its
/// signature): method blocks, property accessor lists, expression bodies.
const SHAPE_BODY_KINDS: [&str; 3] = ["block", "accessor_list", "arrow_expression_clause"];

/// A type needs at least this many distinct member signatures to be compared.
/// Below it the shape is too generic to mean anything (noise control).
const SHAPE_MIN_MEMBERS: usize = 3;

/// True for declaration_list children that are real members (property, field,
/// method, constructor, event, indexer, operator) rather than nested types.
fn is_shape_member(kind: &str) -> bool {
    kind.ends_with("_declaration")
        && !matches!(
            kind,
            "class_declaration"
                | "struct_declaration"
                | "record_declaration"
                | "interface_declaration"
                | "enum_declaration"
                | "delegate_declaration"
                | "namespace_declaration"
        )
}

/// A single member's signature: its source text up to its body (block /
/// accessors / arrow), trailing punctuation stripped and whitespace collapsed.
/// Identifiers and types are kept, so `int Age` and `string Name` are distinct.
fn member_signature(member: Node, src: &str) -> Option<String> {
    let mut end = member.end_byte();
    let mut cur = member.walk();
    for child in member.children(&mut cur) {
        if SHAPE_BODY_KINDS.contains(&child.kind()) {
            end = child.start_byte();
            break;
        }
    }
    let raw = src.get(member.start_byte()..end)?;
    let trimmed = raw.trim().trim_end_matches([';', '{']).trim_end();
    if trimmed.is_empty() {
        return None;
    }
    Some(trimmed.split_whitespace().collect::<Vec<_>>().join(" "))
}

/// Canonical constructor signature: just the parameter types, e.g. `ctor(Graph)`.
/// A classic `constructor_declaration` and a C# primary constructor on the class
/// header both normalize to this, so the two forms of the same class match (#27).
fn constructor_signature(param_list: Node, src: &str) -> String {
    let mut types = Vec::new();
    let mut cur = param_list.walk();
    for param in param_list.named_children(&mut cur) {
        if param.kind() != "parameter" {
            continue;
        }
        if let Some(t) = param
            .child_by_field_name("type")
            .and_then(|ty| ty.utf8_text(src.as_bytes()).ok())
        {
            types.push(t.split_whitespace().collect::<Vec<_>>().join(" "));
        }
    }
    format!("ctor({})", types.join(", "))
}

/// Extract one class-shape unit per type declaration whose member-signature set
/// is large enough to be meaningful. Returns plain `FunctionUnit`s (kept in
/// their own vector by the caller) so the existing index/cluster pipeline can
/// compare them by Jaccard over the member-signature set.
pub fn extract_class_shapes(
    file: u32,
    lang: Lang,
    src: &str,
    file_is_test: bool,
) -> Vec<FunctionUnit> {
    let Some(query) = lang.shape_query() else {
        return Vec::new();
    };
    let parsed = PARSER.with(|p| {
        let mut parser = p.borrow_mut();
        parser.set_language(&lang.language()).ok()?;
        parser.parse(src, None)
    });
    let Some(tree) = parsed else {
        return Vec::new();
    };
    let root = tree.root_node();

    let name_idx = query.capture_index_for_name("name");
    let body_idx = query.capture_index_for_name("body");
    let func_idx = query.capture_index_for_name("func");

    let mut units = Vec::new();
    let mut cursor = QueryCursor::new();
    let mut matches = cursor.matches(query, root, src.as_bytes());
    while let Some(m) = matches.next() {
        let mut name = None;
        let mut body = None;
        let mut func = None;
        for cap in m.captures {
            if Some(cap.index) == name_idx {
                name = Some(cap.node);
            } else if Some(cap.index) == body_idx {
                body = Some(cap.node);
            } else if Some(cap.index) == func_idx {
                func = Some(cap.node);
            }
        }
        let (Some(body), Some(func)) = (body, func) else {
            continue;
        };

        let mut fingerprints: Vec<u64> = Vec::new();
        let push_sig = |fps: &mut Vec<u64>, sig: &str| {
            let mut h = FxHasher::default();
            sig.hash(&mut h);
            fps.push(h.finish());
        };
        let mut walker = body.walk();
        for member in body.named_children(&mut walker) {
            if !is_shape_member(member.kind()) {
                continue;
            }
            // A constructor is canonicalized to its parameter types (`ctor(Graph)`)
            // so a class using a classic constructor matches one that moved the
            // same constructor onto the class header as a primary constructor (#27).
            let sig = if member.kind() == "constructor_declaration" {
                member
                    .child_by_field_name("parameters")
                    .map(|pl| constructor_signature(pl, src))
            } else {
                member_signature(member, src)
            };
            if let Some(sig) = sig {
                push_sig(&mut fingerprints, &sig);
            }
        }
        // C# primary constructor: its parameters live on the class header, not as
        // a body member, so synthesize the same canonical signature here (#27).
        let mut fwalk = func.walk();
        for child in func.children(&mut fwalk) {
            if child.kind() == "parameter_list" {
                push_sig(&mut fingerprints, &constructor_signature(child, src));
                break;
            }
        }
        fingerprints.sort_unstable();
        fingerprints.dedup();
        if fingerprints.len() < SHAPE_MIN_MEMBERS {
            continue;
        }

        let name = name
            .and_then(|n| n.utf8_text(src.as_bytes()).ok())
            .unwrap_or("<anonymous>")
            .to_string();
        // sig_lines doubles as the member count here: it drives representative
        // choice (most members wins) and the report's per-class member tally.
        let member_count = fingerprints.len() as u32;
        units.push(FunctionUnit {
            file,
            lang,
            name,
            start_line: func.start_position().row as u32 + 1,
            end_line: func.end_position().row as u32 + 1,
            start_byte: func.start_byte() as u32,
            end_byte: func.end_byte() as u32,
            sig_lines: member_count,
            fingerprints,
            is_test: file_is_test,
            is_trait_impl_method: false,
        });
    }
    units
}

#[cfg(test)]
mod tests {
    use super::*;

    const TS_PAIR: &str = r#"
export function formatPrice(value: number, currency: string): string {
    const rounded = Math.round(value * 100) / 100;
    const parts = rounded.toFixed(2).split(".");
    const whole = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    if (currency === "USD") {
        return "$" + whole + "." + parts[1];
    }
    return whole + "." + parts[1] + " " + currency;
}

export function displayCurrency(amount: number, code: string): string {
    const r = Math.round(amount * 100) / 100;
    const pieces = r.toFixed(2).split(".");
    const integer = pieces[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    if (code === "EUR") {
        return "$" + integer + "." + pieces[1];
    }
    return integer + "." + pieces[1] + " " + code;
}
"#;

    #[test]
    fn extracts_typescript_functions_with_spans() {
        let fa = analyze_source(0, Lang::Typescript, TS_PAIR, 10, false).unwrap();
        assert_eq!(fa.functions.len(), 2);
        assert_eq!(fa.functions[0].name, "formatPrice");
        assert_eq!(fa.functions[1].name, "displayCurrency");
        assert_eq!(fa.functions[0].start_line, 2);
        assert!(fa.functions[0].sig_lines >= 8);
    }

    #[test]
    fn renamed_clone_has_identical_fingerprints() {
        // The two functions differ only in identifiers and literals — a
        // textbook type-2 clone. Normalization must make them identical.
        let fa = analyze_source(0, Lang::Typescript, TS_PAIR, 10, false).unwrap();
        assert_eq!(fa.functions[0].fingerprints, fa.functions[1].fingerprints);
    }

    #[test]
    fn different_logic_does_not_match() {
        let src = r#"
function sumEvens(xs: number[]): number {
    let total = 0;
    for (const x of xs) {
        if (x % 2 === 0) total += x;
    }
    return total;
}

function describeUser(user: { name: string; age: number }): string {
    if (user.age >= 18) {
        return user.name + " is an adult";
    }
    const wait = 18 - user.age;
    return user.name + " can vote in " + wait + " years";
}
"#;
        let fa = analyze_source(0, Lang::Typescript, src, 10, false).unwrap();
        assert_eq!(fa.functions.len(), 2);
        let j = crate::fingerprint::jaccard(
            &fa.functions[0].fingerprints,
            &fa.functions[1].fingerprints,
        );
        assert!(j < 0.3, "unrelated functions scored {j}");
    }

    #[test]
    fn comments_do_not_affect_fingerprints() {
        let without = "function f(a: number) {\n  const b = a * 2;\n  const c = b + a * 7;\n  if (c > 10) { return c - b; }\n  return a + b + c;\n}";
        let with = "function f(a: number) {\n  // doubles the input\n  const b = a * 2;\n  /* magic */ const c = b + a * 7;\n  if (c > 10) { return c - b; }\n  return a + b + c; // done\n}";
        let fa1 = analyze_source(0, Lang::Typescript, without, 5, false).unwrap();
        let fa2 = analyze_source(0, Lang::Typescript, with, 5, false).unwrap();
        assert_eq!(fa1.functions[0].fingerprints, fa2.functions[0].fingerprints);
    }

    // Clojure's grammar represents operators, special forms, macros, and
    // ordinary identifiers with the same `sym_name` node kind — unlike every
    // other supported grammar, which gives keywords/operators their own
    // distinct kinds separate from `identifier`. These two tests are the
    // real regression guard for that: the TypeScript pair above proves
    // normalization's core invariant once; this proves it still holds once
    // a language can't lean on kind-name alone to tell "+" from "x".
    const CLOJURE_PAIR: &str = r#"
(defn sum-items [items factor]
  (let [total (reduce (fn [acc item]
                         (let [value (* (:price item) (:qty item))]
                           (if (:discount item)
                             (+ acc (* value (- 1.0 (:discount item))))
                             (+ acc value))))
                       0.0
                       items)]
    (+ total (* total factor))))

(defn combine-totals [rows scale]
  (let [sum (reduce (fn [acc row]
                       (let [amount (* (:price row) (:qty row))]
                         (if (:discount row)
                           (+ acc (* amount (- 1.0 (:discount row))))
                           (+ acc amount))))
                     0.0
                     rows)]
    (+ sum (* sum scale))))
"#;

    #[test]
    fn clojure_renamed_clone_has_identical_fingerprints() {
        // Same shape, every local variable/parameter renamed, operators and
        // special forms (defn, let, reduce, fn, if, +, *, -) untouched — a
        // textbook type-2 clone. 4 functions, not 2: each defn's nested
        // (fn [acc item] ...) reducer is now its own <anonymous> unit too
        // (bare/unbound fn literals are captured unconditionally), and
        // those two should be an identical clone of each other as well.
        let fa = analyze_source(0, Lang::Clojure, CLOJURE_PAIR, 10, false).unwrap();
        assert_eq!(fa.functions.len(), 4);
        let named: Vec<_> = fa
            .functions
            .iter()
            .filter(|f| f.name != "<anonymous>")
            .collect();
        let anon: Vec<_> = fa
            .functions
            .iter()
            .filter(|f| f.name == "<anonymous>")
            .collect();
        assert_eq!(named.len(), 2);
        assert_eq!(anon.len(), 2);
        assert_eq!(named[0].fingerprints, named[1].fingerprints);
        assert_eq!(anon[0].fingerprints, anon[1].fingerprints);
    }

    #[test]
    fn clojure_different_logic_does_not_match() {
        // Same nesting shape, same literal-type pattern, but different verbs
        // throughout (max/when/min/- instead of */if/+). Before TokenClass::Op
        // exists, every symbol collapses to the same code regardless of kind,
        // so this is expected to FAIL — it's the concrete proof the fix does
        // what it claims once it lands. 4 functions, not 2, for the same
        // reason as the renamed-clone test above: each nested reducer fn is
        // its own <anonymous> unit, and it differs in the same way its
        // enclosing defn does.
        let src = r#"
(defn sum-items [items factor]
  (let [total (reduce (fn [acc item]
                         (let [value (* (:price item) (:qty item))]
                           (if (:discount item)
                             (+ acc (* value (- 1.0 (:discount item))))
                             (+ acc value))))
                       0.0
                       items)]
    (+ total (* total factor))))

(defn max-items [items factor]
  (let [total (reduce (fn [acc item]
                         (let [value (max (:price item) (:qty item))]
                           (when (:discount item)
                             (- acc (min value (/ 1.0 (:discount item)))))
                           (- acc value)))
                       0.0
                       items)]
    (- total (/ total factor))))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 10, false).unwrap();
        assert_eq!(fa.functions.len(), 4);
        let named: Vec<_> = fa
            .functions
            .iter()
            .filter(|f| f.name != "<anonymous>")
            .collect();
        let anon: Vec<_> = fa
            .functions
            .iter()
            .filter(|f| f.name == "<anonymous>")
            .collect();
        assert_eq!(named.len(), 2);
        assert_eq!(anon.len(), 2);
        let j_named = crate::fingerprint::jaccard(&named[0].fingerprints, &named[1].fingerprints);
        assert!(j_named < 0.3, "unrelated functions scored {j_named}");
        let j_anon = crate::fingerprint::jaccard(&anon[0].fingerprints, &anon[1].fingerprints);
        assert!(j_anon < 0.3, "unrelated nested reducers scored {j_anon}");
    }

    #[test]
    fn clojure_deftest_forms_are_captured() {
        // clojure.test's `deftest` isn't literally `defn`, so it needs its
        // own arm in the query's #any-of? list — without it, every deftest
        // in a real codebase's test suite is invisible to dupehound.
        let src = r#"
(defn add-one [x]
  (+ x 1))

(deftest add-one-test
  (testing "adds one"
    (is (= 2 (add-one 1)))
    (is (= 3 (add-one 2)))))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 5, false).unwrap();
        let names: Vec<&str> = fa.functions.iter().map(|f| f.name.as_str()).collect();
        assert_eq!(names, vec!["add-one", "add-one-test"]);
    }

    #[test]
    fn clojure_def_bound_fn_is_captured() {
        // (def name (fn [args] ...)) is the def+fn idiom, equivalent to
        // (defn name [args] ...) -- mirrors javascript.scm's
        // variable_declarator pattern for `const name = () => {...}`.
        // len() == 1, not 2: dupehound intentionally has no bare/anonymous
        // -fn pattern (same javascript.scm precedent -- arrow functions are
        // only matched when bound to a name), so the inner (fn ...) node
        // is captured exactly once, by this pattern alone.
        let src = r#"
(def add-one (fn [x]
  (+ x 1)))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
        assert_eq!(fa.functions.len(), 1);
        assert_eq!(fa.functions[0].name, "add-one");
    }

    #[test]
    fn clojure_plain_def_is_not_a_function() {
        // (def x 5) and (def config {...}) bind data, not a function value
        // -- only a def whose value is (fn ...) should match.
        let src = r#"
(def just-data
  {:a 1 :b 2})

(def aliased +)
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
        assert!(
            fa.functions.is_empty(),
            "expected no functions, got {:?}",
            fa.functions.iter().map(|f| &f.name).collect::<Vec<_>>()
        );
    }

    #[test]
    fn clojure_def_bound_fn_renamed_clone_has_identical_fingerprints() {
        // Two def+fn functions, same shape, renamed variable/parameter --
        // the def+fn idiom needs the same type-2-clone guarantee defn
        // already has. (defn and def+fn are NOT expected to match each
        // other: def+fn's body is just the inner (fn ...) node, so it has
        // no equivalent to defn's own leading "defn"/name tokens -- they're
        // different shapes, not the same stream.)
        let src = r#"
(def add-one (fn [x]
  (+ x 1)))

(def increment (fn [y]
  (+ y 1)))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
        assert_eq!(fa.functions.len(), 2);
        assert_eq!(fa.functions[0].fingerprints, fa.functions[1].fingerprints);
    }

    #[test]
    fn clojure_def_bound_reader_macro_fn_is_captured() {
        // (def name #(...)) -- the reader-macro shorthand for def+fn. #(...)
        // is a different grammar node (anon_fn_lit) from (fn ...), so it
        // needs its own pattern; this proves that pattern works and that
        // dedup still keeps exactly one, named, unit -- not two. Body has to
        // clear KGRAM=10 leaf tokens or winnow() produces no fingerprints
        // and the unit is dropped regardless of min_tokens -- a plain
        // `#(+ % 1)` is too short to prove anything here.
        let src = r#"
(def compute #(+ (* % 2) (- % 1) 3))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
        assert_eq!(fa.functions.len(), 1);
        assert_eq!(fa.functions[0].name, "compute");
    }

    #[test]
    fn clojure_letfn_bindings_are_captured() {
        // letfn's bindings are a third shape: list_lit entries nested inside
        // the binding vector, not direct children of the letfn form or
        // headed by any keyword of their own.
        let src = r#"
(defn caller [xs]
  (letfn [(helper [x] (+ x 1))
          (other [y] (* y 2))]
    (map helper xs)))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
        let names: Vec<&str> = fa.functions.iter().map(|f| f.name.as_str()).collect();
        assert!(names.contains(&"caller"));
        assert!(names.contains(&"helper"));
        assert!(names.contains(&"other"));
    }

    #[test]
    fn clojure_letfn_renamed_clone_has_identical_fingerprints() {
        let src = r#"
(letfn [(helper [x] (+ x 1))]
  (helper 1))

(letfn [(increment [y] (+ y 1))]
  (increment 1))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
        let helper = fa.functions.iter().find(|f| f.name == "helper").unwrap();
        let increment = fa.functions.iter().find(|f| f.name == "increment").unwrap();
        assert_eq!(helper.fingerprints, increment.fingerprints);
    }

    #[test]
    fn clojure_bare_lambda_passed_as_callback_is_captured_as_anonymous() {
        // A (fn ...) or #(...) never bound to any name anywhere -- the most
        // common shape in idiomatic Clojure (map/filter/reduce callbacks) --
        // is still captured, reported as "<anonymous>" (the same fallback
        // every other language already uses for unnamed functions).
        let src = r#"
(defn caller [xs]
  (map (fn [x] (+ x 1)) xs))
"#;
        let fa = analyze_source(0, Lang::Clojure, src, 1, false).unwrap();
