    pub repo: String,
    pub series: Vec<Point>,
    /// "duplication grew Nx since DATE", when the data supports it.
    pub growth_factor: Option<f64>,
    pub growth_since: Option<String>,
    pub current_grade: char,
}

pub fn run(args: HistoryArgs) -> Result<i32> {
    let config = Config::from_common(&args.common, DEFAULT_SCAN_THRESHOLD);
    let repo = repo_root(&args.path)?;
    let snapshots = pick_snapshots(&repo, args.max_snapshots)?;
    if snapshots.len() < 2 {
        eprintln!(
            "dupehound history: not enough history to chart ({} usable snapshot{})",
            snapshots.len(),
            if snapshots.len() == 1 { "" } else { "s" }
        );
        return Ok(2);
    }

    let mut cache: BlobCache = FxHashMap::default();
    let mut reader = BlobReader::open(&repo)?;
    let mut series = Vec::with_capacity(snapshots.len());
    for (commit, month) in &snapshots {
        let point = measure(&repo, commit, month, &config, &mut cache, &mut reader)?;
        series.push(point);
    }

    let (growth_factor, growth_since) = inflection(&series);
    let current_grade = grade(series.last().map(|p| p.slop_percent).unwrap_or(0.0));
    let report = HistoryReport {
        schema_version: crate::report::JSON_SCHEMA_VERSION,
        repo: repo_name(&repo),
        series,
        growth_factor,
        growth_since,
        current_grade,
    };

    if config.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print!("{}", render(&report));
    }

    #[cfg(feature = "card")]
    if !args.no_card {
        let svg = crate::report::card::history_card(&report);
        crate::report::card::write_card(&svg, std::path::Path::new("."))?;
        eprintln!("  card written → dupehound-card.svg / dupehound-card.png");
    }

    Ok(0)
}

/// blob oid -> analysis (None = skipped file).
type BlobCache = FxHashMap<String, Option<CachedFile>>;

#[derive(Clone)]
struct CachedFile {
    functions: Vec<FunctionUnit>,
    sig_lines: u32,
}

fn measure(
    repo: &std::path::Path,
    commit: &str,
    month: &str,
    config: &Config,
    cache: &mut BlobCache,
    reader: &mut BlobReader,
) -> Result<Point> {
    let entries: Vec<_> = ls_tree(repo, commit)?
        .into_iter()
        .filter(|e| {
            Lang::from_path(&e.path).is_some()
                && !(config.default_excludes && default_excluded(&e.path))
        })
        .collect();

    // Read blobs we haven't fingerprinted yet (sequential IO, parallel CPU).
    let missing: Vec<&crate::gitsnap::TreeEntry> = entries
        .iter()
        .filter(|e| !cache.contains_key(&e.oid))
        .collect();
    let mut fresh: Vec<(String, String, Vec<u8>)> = Vec::with_capacity(missing.len());
    for e in missing {
        if let Some(bytes) = reader.read_blob(&e.oid)? {
            if bytes.len() as u64 <= MAX_FILE_BYTES {
                fresh.push((e.oid.clone(), e.path.clone(), bytes));
            } else {
                cache.insert(e.oid.clone(), None);
            }
        } else {
            cache.insert(e.oid.clone(), None);
        }
    }
    let analyzed: Vec<(String, Option<CachedFile>)> = fresh
        .par_iter()
        .map(|(oid, path, bytes)| {
            let analysis = String::from_utf8(bytes.clone()).ok().and_then(|src| {
                if content_skip_reason(&src).is_some() {
                    return None;
                }
                let lang = Lang::from_path(path)?;
                let fa = analyze_source(0, lang, &src, config.min_tokens, is_test_path(path))?;
                Some(CachedFile {
                    functions: fa.functions,
                    sig_lines: fa.sig_lines,
                })
            });
            (oid.clone(), analysis)
        })
        .collect();
    cache.extend(analyzed);

    // Assemble this snapshot from the cache.
    let mut functions: Vec<FunctionUnit> = Vec::new();
    let mut sig_lines = 0u64;
    let mut file_id = 0u32;
    for e in &entries {
        let Some(Some(cached)) = cache.get(&e.oid) else {
            continue;
        };
        sig_lines += cached.sig_lines as u64;
        let is_test = is_test_path(&e.path);
        for f in &cached.functions {
            let mut f = f.clone();
            f.file = file_id;
            f.is_test = f.is_test || is_test;
            functions.push(f);
        }
        file_id += 1;
    }

    let function_count = functions.len() as u32;
    let pairs = find_pairs(&mut functions, config.threshold, MIN_SHARED_PREFILTER);
    let clusters = build_clusters(&functions, &pairs);
    let score = slop_score(&clusters, sig_lines, config.tests);

    Ok(Point {
        commit: commit[..commit.len().min(10)].to_string(),
        date: month.to_string(),
        slop_percent: score.percent,
        significant_lines: sig_lines,
        functions: function_count,
    })
}

/// Mainline commits bucketed by month: the last commit of each month, down-
/// sampled evenly to `max`, always ending at HEAD.
fn pick_snapshots(repo: &std::path::Path, max: usize) -> Result<Vec<(String, String)>> {
    let log = git(
        repo,
        &[
            "log",
            "--first-parent",
            "--reverse",
            "--format=%H %ct",
            "HEAD",
        ],
    )?;
    let mut by_month: Vec<(String, String)> = Vec::new(); // (commit, YYYY-MM)
    for line in log.lines() {
        let Some((hash, ts)) = line.split_once(' ') else {
            continue;
        };
        let Ok(ts) = ts.trim().parse::<i64>() else {
            continue;
        };
        let month = month_of(ts);
        match by_month.last_mut() {
            Some(last) if last.1 == month => last.0 = hash.to_string(),
            _ => by_month.push((hash.to_string(), month)),
        }
    }
    if by_month.is_empty() {
        return Ok(vec![]);
    }
    // Young repo: fall back to evenly spaced commits instead of months.
    if by_month.len() < 6 {
        let all: Vec<(String, String)> = log
            .lines()
            .filter_map(|l| {
                let (hash, ts) = l.split_once(' ')?;
                let ts: i64 = ts.trim().parse().ok()?;
                Some((hash.to_string(), month_of(ts)))
            })
            .collect();
        return Ok(evenly_spaced(&all, max.min(12)));
    }
    Ok(evenly_spaced(&by_month, max))
}

fn evenly_spaced(items: &[(String, String)], max: usize) -> Vec<(String, String)> {
    if items.len() <= max {
        return items.to_vec();
    }
    let mut picked = Vec::with_capacity(max);
    for i in 0..max {
        let idx = i * (items.len() - 1) / (max - 1);
        picked.push(items[idx].clone());
    }
    picked.dedup_by(|a, b| a.0 == b.0);
    picked
}

/// Unix timestamp -> "YYYY-MM" (civil-from-days, Howard Hinnant's algorithm).
fn month_of(ts: i64) -> String {
    let days = ts.div_euclid(86_400);
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if month <= 2 { year + 1 } else { year };
    format!("{year:04}-{month:02}")
}

/// Headline growth: current slop vs the minimum of the 3-point smoothed
/// series. Honest when flat: under 1.5x we report nothing.
fn inflection(series: &[Point]) -> (Option<f64>, Option<String>) {
    if series.len() < 3 {
        return (None, None);
    }
    let smoothed: Vec<f64> = (0..series.len())
        .map(|i| {
            let lo = i.saturating_sub(1);
            let hi = (i + 1).min(series.len() - 1);
            let window = &series[lo..=hi];
            window.iter().map(|p| p.slop_percent).sum::<f64>() / window.len() as f64
        })
        .collect();
    let current = *smoothed.last().unwrap();
    let (min_idx, min_val) = smoothed
        .iter()
        .enumerate()
        .min_by(|a, b| a.1.partial_cmp(b.1).unwrap())
        .map(|(i, v)| (i, *v))
        .unwrap();
    if min_val <= 0.05 {
        // Effectively from zero: a ratio is meaningless, so report the end
        // of the clean era instead (rendered as "went from ~0 to X%").
        if current >= 1.0 {
            // Raw series, not smoothed: smoothing bleeds the first dirty
            // month backwards and would misdate the clean era's end.
            let last_clean = series
                .iter()
                .rposition(|p| p.slop_percent <= 0.05)
                .unwrap_or(0);
            if last_clean < series.len() - 1 {
                return (None, Some(series[last_clean].date.clone()));
            }
        }
        return (None, None);
    }
    let factor = current / min_val;
    if factor >= 1.5 && min_idx < series.len() - 1 {
        (Some(factor), Some(series[min_idx].date.clone()))
    } else {
        (None, None)
    }
}

fn repo_name(repo: &std::path::Path) -> String {
    repo.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| repo.display().to_string())
}

const CHART_HEIGHT: usize = 7;

fn render(r: &HistoryReport) -> String {
    use owo_colors::{OwoColorize, Stream::Stdout};
    let dim = |s: &str| s.if_supports_color(Stdout, |t| t.dimmed()).to_string();
    let bold = |s: &str| s.if_supports_color(Stdout, |t| t.bold()).to_string();

    let mut out = String::new();
    let current = r.series.last().unwrap();
    out.push('\n');
    out.push_str(&dim(&format!(
        "  dupehound history — {} · {} snapshots · {} → {}",
        r.repo,
        r.series.len(),
        r.series[0].date,
        current.date,
    )));
    out.push_str("\n\n");

    // Chart
    let max = r
        .series
        .iter()
        .map(|p| p.slop_percent)
        .fold(0.0f64, f64::max)
        .max(0.1);
    let cols: Vec<usize> = r
        .series
        .iter()
        .map(|p| ((p.slop_percent / max) * (CHART_HEIGHT * 8) as f64).round() as usize)
        .collect();
    for row in (0..CHART_HEIGHT).rev() {
        let label = if row == CHART_HEIGHT - 1 {
            format!("{max:>5.1}% ")
        } else if row == 0 {
            format!("{:>5.1}% ", 0.0)
        } else {
            "       ".to_string()
        };
        out.push_str(&dim(&format!("  {label}┤")));
        for &c in &cols {
            let cell = c.saturating_sub(row * 8).min(8);
            let ch = [" ", "▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"][cell];
            out.push_str(ch);
            out.push_str(ch); // two chars per snapshot for visibility
        }
        out.push('\n');
    }
    out.push_str(&dim(&format!(
        "         └{}\n",
        "─".repeat(r.series.len() * 2)
    )));
    let axis_width = (r.series.len() * 2).saturating_sub(7);
    out.push_str(&dim(&format!(
        "          {}{:>axis_width$}\n",
        r.series[0].date, current.date,
    )));
    out.push('\n');

    out.push_str(&format!(
        "  current slop score: {} (grade {})\n",
        bold(&format!("{:.1}%", current.slop_percent)),
        grade(current.slop_percent),
    ));
    out.push_str(&match (&r.growth_factor, &r.growth_since) {
        (Some(factor), Some(since)) => format!(
            "  {} {}\n",
            bold(&format!("duplication grew {factor:.1}× since {since}")),
            dim("(vs the smoothed minimum)"),
        ),
        (None, Some(since)) => format!(
            "  {}\n",
            bold(&format!(
                "duplication went from ~0 to {:.1}% since {since}",
                current.slop_percent
            )),
        ),
        _ => dim("  no significant duplication growth detected\n"),
    });
    out.push('\n');
    out
}

//! Inverted fingerprint index and candidate pair generation. This is the
//! O(n²) firewall: functions only ever get compared when they already share
//! fingerprints, and ultra-common fingerprints (language boilerplate) are
//! culled before they can pair everything with everything.

use crate::extract::FunctionUnit;
use crate::fingerprint::jaccard;
use rayon::prelude::*;
use rustc_hash::{FxHashMap, FxHashSet};

pub struct Pair {
    pub a: u32,
    pub b: u32,
}

/// Cull fingerprints shared by more than this many functions: they are
/// idiom, not duplication (think `if err != nil` ladders). The cap scales
/// with corpus size but never drops below 100.
fn cull_cap(function_count: usize) -> usize {
    (function_count / 200).max(100)
}

/// Find all pairs of functions with Jaccard similarity >= `threshold`.
/// Functions are only compared within the same language. As a side effect,
/// culled fingerprints are removed from every function's fingerprint set so
/// downstream similarity math stays consistent.
pub fn find_pairs(functions: &mut [FunctionUnit], threshold: f64, min_shared: u32) -> Vec<Pair> {
    let mut by_lang: FxHashMap<crate::lang::Lang, Vec<u32>> = FxHashMap::default();
    for (i, f) in functions.iter().enumerate() {
        by_lang.entry(f.lang).or_default().push(i as u32);
    }

    let mut pairs = Vec::new();
    for ids in by_lang.values() {
        cull(functions, ids);
        pairs.extend(pairs_within(functions, ids, threshold, min_shared));
    }
    pairs
}

fn cull(functions: &mut [FunctionUnit], ids: &[u32]) {
    let cap = cull_cap(ids.len());
    let mut counts: FxHashMap<u64, u32> = FxHashMap::default();
    for &id in ids {
        for &fp in &functions[id as usize].fingerprints {
            *counts.entry(fp).or_insert(0) += 1;
        }
    }
    let culled: FxHashSet<u64> = counts
        .into_iter()
        .filter(|&(_, n)| n as usize > cap)
        .map(|(fp, _)| fp)
        .collect();
    if culled.is_empty() {
        return;
    }
    for &id in ids {
        functions[id as usize]
            .fingerprints
            .retain(|fp| !culled.contains(fp));
    }
}

fn pairs_within(
    functions: &[FunctionUnit],
    ids: &[u32],
    threshold: f64,
    min_shared: u32,
) -> Vec<Pair> {
    // Posting lists hold positions within `ids` (ascending), so candidate
    // generation can restrict to strictly-later functions and count each
    // pair exactly once.
    let mut postings: FxHashMap<u64, Vec<u32>> = FxHashMap::default();
    for (pos, &id) in ids.iter().enumerate() {
        for &fp in &functions[id as usize].fingerprints {
            postings.entry(fp).or_default().push(pos as u32);
        }
    }

    ids.par_iter()
        .enumerate()
        .flat_map_iter(|(pos, &id)| {
            let me = &functions[id as usize];
            let mut shared: FxHashMap<u32, u32> = FxHashMap::default();
            for fp in &me.fingerprints {
                if let Some(list) = postings.get(fp) {
                    // Lists are sorted; only look at functions after `pos`.
                    let start = list.partition_point(|&p| p <= pos as u32);
                    for &other in &list[start..] {
                        *shared.entry(other).or_insert(0) += 1;
                    }
                }
            }
            let mut found = Vec::new();
            for (other_pos, count) in shared {
                if count < min_shared {
                    continue;
                }
                let other_id = ids[other_pos as usize];
                let other = &functions[other_id as usize];
                // Fingerprint vecs are distinct sets, so the shared count
                // *is* the exact intersection size.
                let union = me.fingerprints.len() + other.fingerprints.len() - count as usize;
                let similarity = if union == 0 {
                    0.0
                } else {
                    count as f64 / union as f64
                };
                if similarity >= threshold {
                    found.push(Pair { a: id, b: other_id });
                }
            }
            found
        })
        .collect()
}

/// Similarity of two specific functions over their (post-cull) fingerprints.
pub fn similarity(a: &FunctionUnit, b: &FunctionUnit) -> f64 {
    jaccard(&a.fingerprints, &b.fingerprints)
}

/// A small function whose fingerprints are almost entirely contained in a
/// larger one — the "copied into a bigger function" case Jaccard misses,
/// because the larger body inflates the union while the intersection stays
/// bounded by the small one.
pub struct ContainmentPair {
    pub small: u32,
    pub large: u32,
    /// shared / |small fingerprints|: how much of the small function the
    /// larger one covers (0.0-1.0).
    pub containment: f64,
}

/// Find containment pairs the normal (Jaccard) scan misses: the smaller
/// function is at least `containment_threshold` covered by the larger one, yet
/// their Jaccard stays below `jaccard_threshold`. Runs on the post-cull
/// fingerprints, so it must be called *after* `find_pairs`. Pairs where one
/// function is lexically nested inside the other (a closure inside its parent)
/// are dropped: that overlap is structural, not a copy.
pub fn find_containment(
    functions: &[FunctionUnit],
    jaccard_threshold: f64,
    containment_threshold: f64,
    min_shared: u32,
) -> Vec<ContainmentPair> {
    let mut by_lang: FxHashMap<crate::lang::Lang, Vec<u32>> = FxHashMap::default();
    for (i, f) in functions.iter().enumerate() {
        by_lang.entry(f.lang).or_default().push(i as u32);
    }
    let mut out = Vec::new();
    for ids in by_lang.values() {
        out.extend(containment_within(
            functions,
            ids,
            jaccard_threshold,
            containment_threshold,
            min_shared,
        ));
    }
    out
}

fn containment_within(
    functions: &[FunctionUnit],
    ids: &[u32],
    jaccard_threshold: f64,
    containment_threshold: f64,
    min_shared: u32,
) -> Vec<ContainmentPair> {
    let mut postings: FxHashMap<u64, Vec<u32>> = FxHashMap::default();
    for (pos, &id) in ids.iter().enumerate() {
        for &fp in &functions[id as usize].fingerprints {
            postings.entry(fp).or_default().push(pos as u32);
        }
    }

    ids.par_iter()
        .enumerate()
        .flat_map_iter(|(pos, &id)| {
            let me = &functions[id as usize];
            let mut shared: FxHashMap<u32, u32> = FxHashMap::default();
            for fp in &me.fingerprints {
                if let Some(list) = postings.get(fp) {
                    let start = list.partition_point(|&p| p <= pos as u32);
                    for &other in &list[start..] {
                        *shared.entry(other).or_insert(0) += 1;
                    }
                }
            }
            let mut found = Vec::new();
            for (other_pos, count) in shared {
                if count < min_shared {
                    continue;
                }
                let other_id = ids[other_pos as usize];
                let other = &functions[other_id as usize];
                let (la, lb) = (me.fingerprints.len(), other.fingerprints.len());
                let union = la + lb - count as usize;
                let jaccard = if union == 0 {
                    0.0
                } else {
                    count as f64 / union as f64
                };
                // Above the Jaccard bar it is already a normal-scan cluster.
                if jaccard >= jaccard_threshold {
                    continue;
                }
                let min_len = la.min(lb);
                if min_len == 0 {
                    continue;
                }
                let containment = count as f64 / min_len as f64;
                if containment < containment_threshold {
                    continue;
                }
                // The smaller fingerprint set is the one being "contained".
                let (small, large) = if la <= lb {
                    (id, other_id)
                } else {
                    (other_id, id)
                };
                if lexically_nested(&functions[small as usize], &functions[large as usize]) {
                    continue;
                }
                found.push(ContainmentPair {
                    small,
                    large,
                    containment,
                });
            }
            found
        })
        .collect()
}

/// True when one function's byte range sits inside the other's within the same
/// file — a nested fn or closure that matches only because its parent encloses
/// it, not because it was copied.
fn lexically_nested(a: &FunctionUnit, b: &FunctionUnit) -> bool {
    let inside = |inner: &FunctionUnit, outer: &FunctionUnit| {
        inner.file == outer.file
            && outer.start_byte <= inner.start_byte
            && inner.end_byte <= outer.end_byte
    };
    inside(a, b) || inside(b, a)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lang::Lang;

    fn unit(file: u32, bytes: (u32, u32), fps: Vec<u64>) -> FunctionUnit {
        FunctionUnit {
            file,
            lang: Lang::Typescript,
            name: "f".into(),
            start_line: 1,
            end_line: 10,
            start_byte: bytes.0,
            end_byte: bytes.1,
            sig_lines: 10,
            fingerprints: fps,
            is_test: false,
            is_trait_impl_method: false,
        }
    }

    #[test]
    fn small_copied_into_large_is_reported() {
        // 10-fp function fully contained in a 30-fp one, in different files.
        // Jaccard = 10/30 = 0.33 (below 0.80), containment = 10/10 = 1.0.
        let small = (1..=10).collect::<Vec<u64>>();
        let large = (1..=30).collect::<Vec<u64>>();
        let functions = vec![unit(0, (0, 100), small), unit(1, (0, 900), large)];
        let pairs = find_containment(&functions, 0.80, 0.90, 3);
        assert_eq!(pairs.len(), 1);
        assert_eq!(pairs[0].small, 0);
        assert_eq!(pairs[0].large, 1);
        assert!((pairs[0].containment - 1.0).abs() < 1e-9);
    }

    #[test]
    fn lexically_nested_pair_is_skipped() {
        // Same file, small's byte range inside large's: a nested closure, not
        // a copy. Must not be reported even though containment is 1.0.
        let small = (1..=10).collect::<Vec<u64>>();
        let large = (1..=30).collect::<Vec<u64>>();
        let functions = vec![unit(0, (100, 400), small), unit(0, (0, 900), large)];
        let pairs = find_containment(&functions, 0.80, 0.90, 3);
        assert!(pairs.is_empty());
    }

    #[test]
    fn near_identical_pair_stays_with_jaccard_scan() {
        // Two same-size functions the normal scan already clusters (Jaccard
        // 1.0) are not re-reported as containment findings.
        let fps = (1..=10).collect::<Vec<u64>>();
        let functions = vec![unit(0, (0, 100), fps.clone()), unit(1, (0, 100), fps)];
        let pairs = find_containment(&functions, 0.80, 0.90, 3);
        assert!(pairs.is_empty());
    }
}

