//! The shareable card: a 1200×630 (OG-image sized) SVG, rasterized to PNG
//! at 2×. Fonts are embedded in the binary so the card renders identically
//! on every machine.

use super::Report;
use crate::history::HistoryReport;
use anyhow::{Context, Result};
use std::path::Path;

const FONT_REGULAR: &[u8] = include_bytes!("../../assets/fonts/JetBrainsMono-Regular.ttf");
const FONT_BOLD: &[u8] = include_bytes!("../../assets/fonts/JetBrainsMono-Bold.ttf");
const FONT_XBOLD: &[u8] = include_bytes!("../../assets/fonts/JetBrainsMono-ExtraBold.ttf");

const W: f64 = 1200.0;
const H: f64 = 630.0;

const BG: &str = "#0d1117";
const PANEL: &str = "#161b22";
const BORDER: &str = "#30363d";
const TEXT: &str = "#e6edf3";
const DIM: &str = "#8b949e";
const GREEN: &str = "#3fb950";
const YELLOW: &str = "#d29922";
const RED: &str = "#f85149";

fn grade_color(grade: char) -> &'static str {
    match grade {
        'A' | 'B' => GREEN,
        'C' => YELLOW,
        _ => RED,
    }
}

fn esc(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

fn frame(body: &str) -> String {
    format!(
        r##"<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">
<rect width="{W}" height="{H}" fill="{BG}"/>
<rect x="1.5" y="1.5" width="{w2}" height="{h2}" rx="14" fill="none" stroke="{BORDER}" stroke-width="3"/>
{body}
<text x="60" y="588" font-family="JetBrains Mono" font-size="20" fill="{DIM}">dupehound — sniffs out the code your AI wrote twice · fast · offline · no AI required</text>
</svg>"##,
        w2 = W - 3.0,
        h2 = H - 3.0,
    )
}

/// Card for `scan --card`: the score, huge.
pub fn score_card(report: &Report) -> String {
    let color = grade_color(report.score.grade);
    let repo = esc(&report.root);
    let pct = format!("{:.1}%", report.score.slop_percent);
    let body = format!(
        r##"<text x="60" y="96" font-family="JetBrains Mono" font-weight="bold" font-size="34" fill="{TEXT}">{repo}</text>
<text x="60" y="146" font-family="JetBrains Mono" font-size="24" fill="{DIM}">SLOP SCORE</text>
<text x="54" y="340" font-family="JetBrains Mono" font-weight="800" font-size="170" fill="{color}">{pct}</text>
<rect x="60" y="386" width="150" height="64" rx="10" fill="{PANEL}" stroke="{BORDER}"/>
<text x="135" y="430" font-family="JetBrains Mono" font-weight="bold" font-size="32" fill="{color}" text-anchor="middle">grade {grade}</text>
<text x="60" y="500" font-family="JetBrains Mono" font-size="24" fill="{DIM}">{deletable} of {total} significant lines are deletable duplicates</text>
"##,
        grade = report.score.grade,
        deletable = group(report.score.deletable_lines),
        total = group(report.stats.significant_lines),
    );
    frame(&body)
}

/// Card for `history`: the area chart with the inflection callout.
pub fn history_card(r: &HistoryReport) -> String {
    let current = r.series.last().expect("non-empty series");
    let color = grade_color(r.current_grade);
    let repo = esc(&r.repo);
    let pct = format!("{:.1}%", current.slop_percent);

    // Chart geometry.
    let (cx, cy, cw, ch) = (60.0, 250.0, 1080.0, 260.0);
    let max = r
        .series
        .iter()
        .map(|p| p.slop_percent)
        .fold(0.0f64, f64::max)
        .max(0.1)
        * 1.15;
    let pts: Vec<(f64, f64)> = r
        .series
        .iter()
        .enumerate()
        .map(|(i, p)| {
            let x = cx + cw * i as f64 / (r.series.len() - 1).max(1) as f64;
            let y = cy + ch - ch * (p.slop_percent / max);
            (x, y)
        })
        .collect();
    let line = smooth_path(&pts);
    let area = format!(
        "{line} L {:.1} {:.1} L {:.1} {:.1} Z",
        pts.last().unwrap().0,
        cy + ch,
        pts[0].0,
        cy + ch
    );

    // Inflection marker: the snapshot where growth was measured from.
    let marker = r
        .growth_since
        .as_ref()
        .and_then(|since| r.series.iter().position(|p| &p.date == since))
        .map(|i| {
            let (x, y) = pts[i];
            format!(
                r##"<circle cx="{x:.1}" cy="{y:.1}" r="7" fill="{BG}" stroke="{color}" stroke-width="3"/>
<line x1="{x:.1}" y1="{y:.1}" x2="{x:.1}" y2="{top}" stroke="{color}" stroke-width="2" stroke-dasharray="4 5" opacity="0.7"/>"##,
                top = cy - 8.0,
            )
        })
        .unwrap_or_default();

    let headline = match (&r.growth_factor, &r.growth_since) {
        (Some(f), Some(since)) => format!("duplication grew {f:.1}× since {since}"),
        (None, Some(since)) => format!(
            "duplication went from ~0 to {:.1}% since {since}",
            current.slop_percent
        ),
        _ => "no significant duplication growth".to_string(),
    };

    let body = format!(
        r##"<text x="60" y="96" font-family="JetBrains Mono" font-weight="bold" font-size="34" fill="{TEXT}">{repo}</text>
<text x="60" y="142" font-family="JetBrains Mono" font-size="22" fill="{DIM}">{from} → {to} · {n} snapshots</text>
<text x="1140" y="96" font-family="JetBrains Mono" font-weight="800" font-size="64" fill="{color}" text-anchor="end">{pct}</text>
<text x="1140" y="138" font-family="JetBrains Mono" font-size="24" fill="{DIM}" text-anchor="end">slop score · grade {grade}</text>
<linearGradient id="fill" x1="0" y1="0" x2="0" y2="1">
  <stop offset="0%" stop-color="{color}" stop-opacity="0.35"/>
  <stop offset="100%" stop-color="{color}" stop-opacity="0.02"/>
</linearGradient>
<line x1="{cx}" y1="{base}" x2="{cx2}" y2="{base}" stroke="{BORDER}" stroke-width="2"/>
<path d="{area}" fill="url(#fill)"/>
<path d="{line}" fill="none" stroke="{color}" stroke-width="4" stroke-linecap="round"/>
{marker}
<text x="60" y="556" font-family="JetBrains Mono" font-weight="bold" font-size="30" fill="{TEXT}">{headline}</text>
"##,
        from = r.series[0].date,
        to = current.date,
        n = r.series.len(),
        grade = r.current_grade,
        base = cy + ch,
        cx2 = cx + cw,
    );
    frame(&body)
}

/// Catmull-Rom spline through the points, emitted as cubic beziers.
fn smooth_path(pts: &[(f64, f64)]) -> String {
    if pts.len() < 2 {
        return String::new();
    }
    let mut d = format!("M {:.1} {:.1}", pts[0].0, pts[0].1);
    for i in 0..pts.len() - 1 {
        let p0 = if i == 0 { pts[0] } else { pts[i - 1] };
        let p1 = pts[i];
        let p2 = pts[i + 1];
        let p3 = if i + 2 < pts.len() { pts[i + 2] } else { p2 };
        let c1 = (p1.0 + (p2.0 - p0.0) / 6.0, p1.1 + (p2.1 - p0.1) / 6.0);
        let c2 = (p2.0 - (p3.0 - p1.0) / 6.0, p2.1 - (p3.1 - p1.1) / 6.0);
        d.push_str(&format!(
            " C {:.1} {:.1}, {:.1} {:.1}, {:.1} {:.1}",
            c1.0, c1.1, c2.0, c2.1, p2.0, p2.1
        ));
    }
    d
}

fn group(n: u64) -> String {
    let s = n.to_string();
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (s.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(c);
    }
    out
}

/// Write the SVG and a 2× PNG next to each other.
pub fn write_card(svg: &str, dir: &Path) -> Result<()> {
    std::fs::write(dir.join("dupehound-card.svg"), svg)?;

    let mut opt = resvg::usvg::Options::default();
    {
        let db = opt.fontdb_mut();
        db.load_font_data(FONT_REGULAR.to_vec());
        db.load_font_data(FONT_BOLD.to_vec());
        db.load_font_data(FONT_XBOLD.to_vec());
    }
    let tree = resvg::usvg::Tree::from_str(svg, &opt).context("parsing card svg")?;
    let mut pixmap = resvg::tiny_skia::Pixmap::new((W * 2.0) as u32, (H * 2.0) as u32)
        .context("allocating pixmap")?;
    resvg::render(
        &tree,
        resvg::tiny_skia::Transform::from_scale(2.0, 2.0),
        &mut pixmap.as_mut(),
    );
    pixmap
        .save_png(dir.join("dupehound-card.png"))
        .context("writing card png")?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::history::Point;

    fn fake_history() -> HistoryReport {
        let series: Vec<Point> = (0..18)
            .map(|i| Point {
                commit: format!("c{i:08}"),
                date: format!("20{:02}-{:02}", 24 + i / 12, 1 + i % 12),
                slop_percent: (i as f64).powf(1.6) / 4.0,
                significant_lines: 10_000 + i as u64 * 500,
                functions: 400 + i as u32 * 13,
            })
            .collect();
        HistoryReport {
            schema_version: 1,
            repo: "acme-api".into(),
            growth_factor: Some(4.1),
            growth_since: Some(series[6].date.clone()),
            current_grade: 'D',
            series,
        }
    }

    #[test]
    fn history_card_renders_svg_and_png() {
        let dir = tempfile::tempdir().unwrap();
        let svg = history_card(&fake_history());
        assert!(svg.contains("acme-api"));
        assert!(svg.contains("4.1×"));
        write_card(&svg, dir.path()).unwrap();
        let png = std::fs::metadata(dir.path().join("dupehound-card.png")).unwrap();
        assert!(png.len() > 20_000, "png suspiciously small: {}", png.len());
        let svg_file = std::fs::metadata(dir.path().join("dupehound-card.svg")).unwrap();
        assert!(svg_file.len() > 1_000);
    }

    #[test]
    fn png_render_is_deterministic() {
        let dir = tempfile::tempdir().unwrap();
        let svg = history_card(&fake_history());
        write_card(&svg, dir.path()).unwrap();
        let first = std::fs::read(dir.path().join("dupehound-card.png")).unwrap();
        write_card(&svg, dir.path()).unwrap();
        let second = std::fs::read(dir.path().join("dupehound-card.png")).unwrap();
        assert_eq!(
            first, second,
            "embedded fonts should make renders identical"
        );
    }
}

pub mod card;
pub mod terminal;

use crate::cluster::Cluster;
use crate::extract::FunctionUnit;
use crate::score::Score;
use serde::Serialize;

// v2: check findings gained an optional `suggestion` (the reuse import line).
pub const JSON_SCHEMA_VERSION: u32 = 2;

#[derive(Serialize)]
pub struct Report {
    pub schema_version: u32,
    pub root: String,
    pub stats: Stats,
    pub score: ScoreOut,
    pub clusters: Vec<ClusterOut>,
    /// Experimental class-shape clusters (`--include-classes`). Omitted from
    /// JSON when empty so the default output is byte-for-byte unchanged.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub class_shapes: Vec<ClusterOut>,
    /// Experimental containment findings (`--containment`): a small function
    /// copied into a larger one. Omitted from JSON when empty.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub containment: Vec<ContainmentOut>,
}

#[derive(Serialize)]
pub struct Stats {
    pub files: u32,
    pub total_lines: u64,
    pub significant_lines: u64,
    pub functions: u32,
    pub elapsed_ms: u64,
    pub skipped_generated: u32,
    pub skipped_minified: u32,
    pub skipped_non_utf8: u32,
}

#[derive(Serialize)]
pub struct ScoreOut {
    /// % of significant lines deletable if every duplicate cluster kept
    /// only one copy.
    pub slop_percent: f64,
    pub grade: char,
    pub deletable_lines: u64,
}

#[derive(Serialize)]
pub struct ClusterOut {
    pub id: usize,
    pub copies: usize,
    /// Mean similarity of the non-representative members to the rep.
    pub similarity: f64,
    pub deletable_lines: u32,
    pub test_only: bool,
    /// Required-name look-alikes (Rust trait impls, Clojure `defmethod`
    /// dispatch branches), kept out of the slop score. Omitted when false so
    /// existing output is unchanged.
    #[serde(default, skip_serializing_if = "is_false")]
    pub trait_impl_only: bool,
    pub members: Vec<MemberOut>,
}

fn is_false(b: &bool) -> bool {
    !*b
}

#[derive(Serialize)]
pub struct MemberOut {
    pub file: String,
    pub name: String,
    pub start_line: u32,
    pub end_line: u32,
    pub lines: u32,
    pub similarity: f64,
    pub representative: bool,
    pub test: bool,
}

#[derive(Serialize)]
pub struct ContainmentOut {
    /// The smaller function, mostly contained in `container`.
    pub contained: ContainmentSide,
    /// The larger function it was copied into.
    pub container: ContainmentSide,
    /// Fraction of the contained function the container covers (0.0-1.0).
    pub containment: f64,
}

#[derive(Serialize)]
pub struct ContainmentSide {
    pub file: String,
    pub name: String,
    pub start_line: u32,
    pub end_line: u32,
    pub lines: u32,
}

/// Map containment pairs to their serializable form. Keeps the strongest
/// container per contained function so one copied helper is reported once, and
/// sorts by the contained function's size (most lines you could extract first).
pub fn containment_out(
    pairs: &[crate::index::ContainmentPair],
    functions: &[FunctionUnit],
    file_names: &[String],
) -> Vec<ContainmentOut> {
    // Best (highest containment) container per contained function.
    let mut best: rustc_hash::FxHashMap<u32, &crate::index::ContainmentPair> =
        rustc_hash::FxHashMap::default();
    for p in pairs {
        best.entry(p.small)
            .and_modify(|cur| {
                if p.containment > cur.containment {
                    *cur = p;
                }
            })
            .or_insert(p);
    }

    let side = |id: u32| {
        let f = &functions[id as usize];
        ContainmentSide {
            file: file_names[f.file as usize].clone(),
            name: f.name.clone(),
            start_line: f.start_line,
            end_line: f.end_line,
            lines: f.sig_lines,
        }
    };

    let mut out: Vec<ContainmentOut> = best
        .values()
        .map(|p| ContainmentOut {
            contained: side(p.small),
            container: side(p.large),
            containment: p.containment,
        })
        .collect();
    out.sort_by(|a, b| {
        b.contained
            .lines
            .cmp(&a.contained.lines)
            .then(b.containment.total_cmp(&a.containment))
            .then(a.contained.file.cmp(&b.contained.file))
            .then(a.contained.start_line.cmp(&b.contained.start_line))
    });
    out
}

/// Map internal clusters to their serializable form. Shared by the function
/// clusters and the experimental class-shape clusters.
pub fn clusters_out(
    clusters: &[Cluster],
    functions: &[FunctionUnit],
    file_names: &[String],
) -> Vec<ClusterOut> {
    clusters
        .iter()
        .enumerate()
        .map(|(i, c)| {
            let mut members: Vec<MemberOut> = c
                .members
                .iter()
                .map(|m| {
                    let f = &functions[m.func as usize];
                    MemberOut {
                        file: file_names[f.file as usize].clone(),
                        name: f.name.clone(),
                        start_line: f.start_line,
                        end_line: f.end_line,
                        lines: f.sig_lines,
                        similarity: m.similarity,
                        representative: false,
                        test: f.is_test,
                    }
                })
                .collect();
            if let Some(first) = members.first_mut() {
                first.representative = true;
            }
            let non_rep: Vec<f64> = c.members[1..].iter().map(|m| m.similarity).collect();
            let similarity = if non_rep.is_empty() {
                1.0
            } else {
                non_rep.iter().sum::<f64>() / non_rep.len() as f64
            };
            ClusterOut {
                id: i + 1,
                copies: c.members.len(),
                similarity,
                deletable_lines: c.deletable_lines,
                test_only: c.test_only,
                trait_impl_only: c.trait_impl_only,
                members,
            }
        })
        .collect()
}

pub fn build(
    root: &str,
    file_names: &[String],
    functions: &[FunctionUnit],
    clusters: &[Cluster],
    score: &Score,
    stats: Stats,
) -> Report {
    // Under TestPolicy::Skip test files were never scanned; under FlagOnly
    // test clusters are shown (labeled) but excluded from the score.
    let clusters_out = clusters_out(clusters, functions, file_names);

    Report {
        schema_version: JSON_SCHEMA_VERSION,
        root: root.to_string(),
        stats,
        score: ScoreOut {
            slop_percent: score.percent,
            grade: score.grade,
            deletable_lines: score.deletable_lines,
        },
        clusters: clusters_out,
        class_shapes: Vec::new(),
        containment: Vec::new(),
    }
}

//! The default terminal report. One-shot output, degrades to plain ASCII
//! when piped or when NO_COLOR is set (owo-colors' supports-colors feature
//! handles detection).

use super::{ClusterOut, Report};
use owo_colors::{OwoColorize, Stream::Stdout};

const TOP_N: usize = 10;

fn dim(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.dimmed()).to_string()
}

fn bold(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.bold()).to_string()
}

fn yellow(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.yellow()).to_string()
}

fn grade_color(s: &str, grade: char) -> String {
    match grade {
        'A' | 'B' => s
            .if_supports_color(Stdout, |t| t.bright_green().bold().to_string())
            .to_string(),
        'C' => s
            .if_supports_color(Stdout, |t| t.yellow().bold().to_string())
            .to_string(),
        _ => s
            .if_supports_color(Stdout, |t| t.bright_red().bold().to_string())
            .to_string(),
    }
}

pub fn render(report: &Report, all: bool) -> String {
    let mut out = String::new();
    header(&mut out, report);
    score_box(&mut out, report);
    clusters(&mut out, report, all);
    footer(&mut out, report);
    out
}

/// Experimental `--include-classes` section, printed after the normal report.
/// Lists C# classes whose property/method signatures largely overlap. This is
/// a separate finding from the function clusters and is not part of the score.
pub fn render_shapes(report: &Report) -> String {
    let mut out = String::new();
    out.push('\n');
    out.push_str(&bold("  CLASS SHAPES  "));
    out.push_str(&dim("(experimental · --include-classes)\n"));
    out.push_str(&dim(
        "  types whose property/method signatures are near-duplicates\n\n",
    ));

    if report.class_shapes.is_empty() {
        out.push_str("  No near-duplicate class shapes found.\n\n");
        return out;
    }

    for c in &report.class_shapes {
        let title = format!(
            "● Shape {} ─ {} classes · {:.0}% shared signatures",
            c.id,
            c.copies,
            c.similarity * 100.0,
        );
        out.push_str(&format!("  {}\n", bold(&title)));
        let loc_width = c
            .members
            .iter()
            .map(|m| format!("{}:{}", m.file, m.start_line).len())
            .max()
            .unwrap_or(0)
            .min(58);
        for m in &c.members {
            let loc = truncate_left(&format!("{}:{}", m.file, m.start_line), loc_width);
            let members = format!("{} members", m.lines);
            if m.representative {
                out.push_str(&format!(
                    "    {} {loc:<loc_width$}  {}  {:>11}\n",
                    yellow("★"),
                    bold(&m.name),
                    members,
                ));
            } else {
                let pct = format!("{:>3.0}%", m.similarity * 100.0);
                out.push_str(&format!(
                    "      {loc:<loc_width$}  {}  {:>11}   {} shared\n",
                    m.name,
                    members,
                    bold(&pct),
                ));
            }
        }
        out.push('\n');
    }
    out.push_str(&dim(
        "  experimental: classes are matched by shared member signatures, not bodies\n",
    ));
    out
}

/// Experimental `--containment` section, printed after the normal report.
/// Lists small functions that are almost entirely copied into a larger one —
/// duplication Jaccard misses because the larger body inflates the union. This
/// is a separate finding from the clusters and is not part of the score.
pub fn render_containment(report: &Report) -> String {
    let mut out = String::new();
    out.push('\n');
    out.push_str(&bold("  CONTAINMENT  "));
    out.push_str(&dim("(experimental · --containment)\n"));
    out.push_str(&dim(
        "  small functions copied into a larger one, which the score misses\n\n",
    ));

    if report.containment.is_empty() {
        out.push_str("  No contained functions found.\n\n");
        return out;
    }

    let loc = |file: &str, line: u32| format!("{file}:{line}");
    let loc_width = report
        .containment
        .iter()
        .flat_map(|c| {
            [
                loc(&c.contained.file, c.contained.start_line).len(),
                loc(&c.container.file, c.container.start_line).len(),
            ]
        })
        .max()
        .unwrap_or(0)
        .min(58);

    for c in &report.containment {
        let pct = format!("{:.0}%", c.containment * 100.0);
        let title = format!(
            "● {} ({} lines) is {} inside a larger function",
            c.contained.name, c.contained.lines, pct,
        );
        out.push_str(&format!("  {}\n", bold(&title)));
        let small_loc = truncate_left(&loc(&c.contained.file, c.contained.start_line), loc_width);
        let large_loc = truncate_left(&loc(&c.container.file, c.container.start_line), loc_width);
        out.push_str(&format!(
            "    {} {small_loc:<loc_width$}  {}\n",
            yellow("↳"),
            dim("copied fragment"),
        ));
        out.push_str(&format!(
            "      {large_loc:<loc_width$}  {}  {}\n",
            c.container.name,
            dim(&format!("{} lines", c.container.lines)),
        ));
        out.push('\n');
    }
    out.push_str(&dim(
        "  experimental: containment ignores the larger body, so review before deleting\n",
    ));
    out
}

fn header(out: &mut String, r: &Report) {
    out.push('\n');
    out.push_str(&dim(&format!(
        "  dupehound v{} — scanned {} files · {} lines · {} functions in {}",
        env!("CARGO_PKG_VERSION"),
        group_digits(r.stats.files as u64),
        group_digits(r.stats.total_lines),
        group_digits(r.stats.functions as u64),
        human_ms(r.stats.elapsed_ms),
    )));
    out.push_str("\n\n");
}

fn score_box(out: &mut String, r: &Report) {
    let pct = format!("{:.1}%", r.score.slop_percent);
    let grade = format!("grade {}", r.score.grade);
    let plain1 = format!("SLOP SCORE   {pct}   {grade}");
    let line2 = format!(
        "{} of {} significant lines are deletable duplicates",
        group_digits(r.score.deletable_lines),
        group_digits(r.stats.significant_lines),
    );
    let inner = line2.len().max(plain1.len()) + 4;

    let line1 = format!(
        "{}   {}   {}",
        bold("SLOP SCORE"),
        grade_color(&pct, r.score.grade),
        dim(&grade)
    );

    out.push_str(&format!("  ╭{}╮\n", "─".repeat(inner)));
    out.push_str(&format!(
        "  │  {}{}│\n",
        line1,
        " ".repeat(inner.saturating_sub(plain1.len() + 2))
    ));
    out.push_str(&format!(
        "  │  {}{}│\n",
        dim(&line2),
        " ".repeat(inner.saturating_sub(line2.len() + 2))
    ));
    out.push_str(&format!("  ╰{}╯\n\n", "─".repeat(inner)));
}

fn clusters(out: &mut String, r: &Report, all: bool) {
    if r.clusters.is_empty() {
        out.push_str("  No duplicate clusters found. Good dog. 🐕\n\n");
        return;
    }
    let shown = if all {
        r.clusters.len()
    } else {
        r.clusters.len().min(TOP_N)
    };
    let hidden = r.clusters.len() - shown;
    out.push_str(&dim(&format!(
        "  {} duplicate cluster{} · showing top {} by deletable lines{}",
        r.clusters.len(),
        if r.clusters.len() == 1 { "" } else { "s" },
        shown,
        if hidden > 0 {
            "  (--all for everything)"
        } else {
            ""
        },
    )));
    out.push_str("\n\n");

    for c in &r.clusters[..shown] {
        render_cluster(out, c);
    }

    if hidden > 0 {
        let hidden_lines: u64 = r.clusters[shown..]
            .iter()
            .map(|c| c.deletable_lines as u64)
            .sum();
        out.push_str(&dim(&format!(
            "  … {} more clusters ({} deletable lines) — run with --all\n",
            hidden,
            group_digits(hidden_lines)
        )));
        out.push('\n');
    }
}

fn render_cluster(out: &mut String, c: &ClusterOut) {
    let test_tag = if c.test_only {
        " · [tests, not scored]"
    } else if c.trait_impl_only {
        " · [trait impls, not scored]"
    } else {
        ""
    };
    let title = format!(
        "● Cluster {} ─ {} copies · {:.0}% similar · {} deletable lines{}",
        c.id,
        c.copies,
        c.similarity * 100.0,
        group_digits(c.deletable_lines as u64),
        test_tag,
    );
    let pad = 78usize.saturating_sub(visible_len(&title) + 3);
    out.push_str(&format!("  {} {}\n", bold(&title), dim(&"─".repeat(pad))));

    let loc_width = c
        .members
        .iter()
        .map(|m| format!("{}:{}", m.file, m.start_line).len())
        .max()
        .unwrap_or(0)
        .min(58);
    let name_width = c
        .members
        .iter()
        .map(|m| m.name.len())
        .max()
        .unwrap_or(0)
        .min(28);

    for m in &c.members {
        let loc = truncate_left(&format!("{}:{}", m.file, m.start_line), loc_width);
        let name = truncate(&m.name, name_width);
        let lines = format!("{} lines", m.lines);
        if m.representative {
            out.push_str(&format!(
                "    {} {loc:<loc_width$}  {name:<name_width$}  {lines:>9}\n",
                yellow("★"),
            ));
        } else {
            let pct = format!("{:>3.0}%", m.similarity * 100.0);
            out.push_str(&format!(
                "      {loc:<loc_width$}  {name:<name_width$}  {lines:>9}   {} {}\n",
                bold(&pct),
                dim(&sim_bar(m.similarity)),
            ));
        }
    }
    out.push('\n');
}

fn footer(out: &mut String, r: &Report) {
    let mut notes: Vec<String> = Vec::new();
    if r.stats.skipped_generated > 0 {
        notes.push(format!("{} generated", r.stats.skipped_generated));
    }
    if r.stats.skipped_minified > 0 {
        notes.push(format!("{} minified", r.stats.skipped_minified));
    }
    if r.stats.skipped_non_utf8 > 0 {
        notes.push(format!("{} non-utf8", r.stats.skipped_non_utf8));
    }
    if !notes.is_empty() {
        out.push_str(&dim(&format!("  skipped files: {}\n", notes.join(" · "))));
    }
    out.push_str(&dim(
        "  slop score = lines deletable if every duplicate cluster kept one copy\n",
    ));
    if !r.clusters.is_empty() {
        out.push_str(&dim(
            "  ★ = representative (kept) · dupehound scan --explain 1 shows the code\n",
        ));
    }
}

/// A 9-cell bar built from eighth-block characters.
fn sim_bar(similarity: f64) -> String {
    let eighths = (similarity.clamp(0.0, 1.0) * 72.0).round() as usize;
    let full = eighths / 8;
    let rem = eighths % 8;
    let blocks = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉"];
    let mut bar = "█".repeat(full.min(9));
    if full < 9 && rem > 0 {
        bar.push_str(blocks[rem]);
    }
    bar
}

fn group_digits(n: u64) -> String {
    let s = n.to_string();
    let mut out = String::with_capacity(s.len() + s.len() / 3);
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (s.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(c);
    }
    out
}

fn human_ms(ms: u64) -> String {
    if ms < 1000 {
        format!("{ms}ms")
    } else {
        format!("{:.1}s", ms as f64 / 1000.0)
    }
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let cut: String = s.chars().take(max.saturating_sub(1)).collect();
        format!("{cut}…")
    }
}

fn truncate_left(s: &str, max: usize) -> String {
    let n = s.chars().count();
    if n <= max {
        s.to_string()
    } else {
        let cut: String = s.chars().skip(n - max + 1).collect();
        format!("…{cut}")
    }
}

fn visible_len(s: &str) -> usize {
    use unicode_width::UnicodeWidthStr;
    s.width()
}

//! The `scan` command: discover files, fingerprint every function, find
//! duplicate clusters, score, report.

use crate::cli::ScanArgs;
use crate::cluster::{Cluster, build_clusters};
use crate::config::{
    Config, DEFAULT_CONTAINMENT_THRESHOLD, DEFAULT_SCAN_THRESHOLD, MIN_SHARED_PREFILTER, TestPolicy,
};
use crate::extract::{FunctionUnit, analyze_source};
use crate::index::{find_containment, find_pairs};
use crate::report::{Report, Stats, build, terminal};
use crate::score::slop_score;
use crate::walk::{DiscoveredFile, discover, load};
use anyhow::Result;
use rayon::prelude::*;
use std::path::Path;
use std::sync::atomic::{AtomicU32, Ordering};
use std::time::Instant;

pub struct ScanOutput {
    pub report: Report,
    pub functions: Vec<FunctionUnit>,
    pub clusters: Vec<Cluster>,
    pub file_paths: Vec<std::path::PathBuf>,
}

pub fn run(args: ScanArgs) -> Result<i32> {
    let mut config = Config::from_common(&args.common, DEFAULT_SCAN_THRESHOLD);
    config.include_classes = args.include_classes;
    config.containment = args.containment;
    let output = scan_path(&args.path, &config)?;

    if let Some(cluster_id) = args.explain {
        print!("{}", explain(&output, cluster_id, args.full)?);
        return Ok(0);
    }

    if config.json {
        println!("{}", serde_json::to_string_pretty(&output.report)?);
    } else {
        print!("{}", terminal::render(&output.report, args.all));
        if config.include_classes {
            print!("{}", terminal::render_shapes(&output.report));
        }
        if config.containment {
            print!("{}", terminal::render_containment(&output.report));
        }
    }

    #[cfg(feature = "card")]
    if args.card {
        let svg = crate::report::card::score_card(&output.report);
        crate::report::card::write_card(&svg, Path::new("."))?;
        eprintln!("  card written → dupehound-card.svg / dupehound-card.png");
    }

    Ok(0)
}

/// Shared scan pipeline (also used by `history` on worktree-less snapshots
/// and by `check` for the base index).
pub fn scan_path(root: &Path, config: &Config) -> Result<ScanOutput> {
    let started = Instant::now();
    let mut discovered = discover(root, config)?;
    if config.tests == TestPolicy::Skip {
        discovered.retain(|f| !f.is_test);
    }

    let skipped_generated = AtomicU32::new(0);
    let skipped_minified = AtomicU32::new(0);
    let skipped_non_utf8 = AtomicU32::new(0);

    struct FileResult {
        rel: String,
        path: std::path::PathBuf,
        functions: Vec<FunctionUnit>,
        shapes: Vec<FunctionUnit>,
        sig_lines: u32,
        total_lines: u32,
    }

    let mut results: Vec<FileResult> = discovered
        .par_iter()
        .filter_map(|f: &DiscoveredFile| {
            let content = match load(&f.path) {
                Ok(Ok(content)) => content,
                Ok(Err("generated")) => {
                    skipped_generated.fetch_add(1, Ordering::Relaxed);
                    return None;
                }
                Ok(Err("minified")) => {
                    skipped_minified.fetch_add(1, Ordering::Relaxed);
                    return None;
                }
                Ok(Err(_)) => {
                    skipped_non_utf8.fetch_add(1, Ordering::Relaxed);
                    return None;
                }
                Err(_) => return None,
            };
            // File id is stamped after the parallel phase (stable order).
            let fa = analyze_source(0, f.lang, &content, config.min_tokens, f.is_test)?;
            let shapes = if config.include_classes {
                crate::extract::extract_class_shapes(0, f.lang, &content, f.is_test)
            } else {
                Vec::new()
            };
            Some(FileResult {
                rel: f.rel.clone(),
                path: f.path.clone(),
                functions: fa.functions,
                shapes,
                sig_lines: fa.sig_lines,
                total_lines: fa.total_lines,
            })
        })
        .collect();
    results.sort_by(|a, b| a.rel.cmp(&b.rel));

    let mut file_names = Vec::with_capacity(results.len());
    let mut file_paths = Vec::with_capacity(results.len());
    let mut functions: Vec<FunctionUnit> = Vec::new();
    let mut shape_functions: Vec<FunctionUnit> = Vec::new();
    let mut total_lines = 0u64;
    let mut sig_lines = 0u64;
    for (i, mut r) in results.into_iter().enumerate() {
        for f in &mut r.functions {
            f.file = i as u32;
        }
        for s in &mut r.shapes {
            s.file = i as u32;
        }
        functions.extend(r.functions);
        shape_functions.extend(r.shapes);
        file_names.push(r.rel);
        file_paths.push(r.path);
        total_lines += r.total_lines as u64;
        sig_lines += r.sig_lines as u64;
    }

    let pairs = find_pairs(&mut functions, config.threshold, MIN_SHARED_PREFILTER);
    let clusters = build_clusters(&functions, &pairs);
    let score = slop_score(&clusters, sig_lines, config.tests);

    // Experimental class-shape track: its own pairs/clusters, never folded
    // into the slop score above.
    let shape_clusters = if config.include_classes {
        let shape_pairs = find_pairs(&mut shape_functions, config.threshold, MIN_SHARED_PREFILTER);
        build_clusters(&shape_functions, &shape_pairs)
    } else {
        Vec::new()
    };

    let stats = Stats {
        files: file_names.len() as u32,
        total_lines,
        significant_lines: sig_lines,
        functions: functions.len() as u32,
        elapsed_ms: started.elapsed().as_millis() as u64,
        skipped_generated: skipped_generated.into_inner(),
        skipped_minified: skipped_minified.into_inner(),
        skipped_non_utf8: skipped_non_utf8.into_inner(),
    };

    let mut report = build(
        &root.display().to_string(),
        &file_names,
        &functions,
        &clusters,
        &score,
        stats,
    );
    if config.include_classes {
        report.class_shapes =
            crate::report::clusters_out(&shape_clusters, &shape_functions, &file_names);
    }

    // Experimental containment track: runs on the post-cull fingerprints left
    // by find_pairs, surfacing small functions copied into a larger one that
    // Jaccard alone misses. Never folded into the slop score.
    if config.containment {
        let pairs = find_containment(
            &functions,
            config.threshold,
            DEFAULT_CONTAINMENT_THRESHOLD,
            MIN_SHARED_PREFILTER,
        );
        report.containment = crate::report::containment_out(&pairs, &functions, &file_names);
    }

    Ok(ScanOutput {
        report,
        functions,
        clusters,
        file_paths,
    })
}

const SIDE_BY_SIDE_MIN_WIDTH: usize = 120;
const DIFF_CONTEXT: usize = 3;

/// A text-styling function (one of the `style::*` color helpers).
type StyleFn = fn(&str) -> String;

/// Show how the copies of a cluster differ from the representative.
///
/// By default this is a colored diff: each copy against the representative, with
/// unchanged runs collapsed and changed tokens emphasized. On a TTY it is
/// side-by-side when the terminal is wide and unified otherwise; piped, it is a
/// plain unified diff that stays grep- and copy-paste-friendly. `--full` prints
/// every body in full instead (numbered and wrapped on a TTY).
fn explain(output: &ScanOutput, cluster_id: usize, full: bool) -> Result<String> {
    use crate::style;

    let Some(cluster) = output.report.clusters.iter().find(|c| c.id == cluster_id) else {
        anyhow::bail!(
            "no cluster {} (there are {})",
            cluster_id,
            output.report.clusters.len()
        );
    };
    let internal = &output.clusters[cluster_id - 1];
    let pretty = style::is_tty();
    let width = style::term_width().unwrap_or(100);

    let mut out = String::new();
    out.push_str(&format!(
        "\n  {}\n\n",
        style::bold(&format!(
            "Cluster {} · {} copies · {:.0}% similar",
            cluster.id,
            cluster.copies,
            cluster.similarity * 100.0
        ))
    ));

    // Read a member's function body from disk by its byte range. Tabs are
    // expanded so the diff's column math matches what the terminal renders.
    let read = |i: usize| -> Option<String> {
        let f = &output.functions[internal.members[i].func as usize];
        let path = &output.file_paths[f.file as usize];
        let content = std::fs::read_to_string(path).ok()?;
        Some(content[f.start_byte as usize..f.end_byte as usize].replace('\t', "    "))
    };

    if full {
        render_full(&mut out, output, internal, &cluster.members, pretty, width);
        return Ok(out);
    }

    let rep_i = cluster
        .members
        .iter()
        .position(|m| m.representative)
        .unwrap_or(0);
    let rep = &cluster.members[rep_i];
    let rep_src = read(rep_i).unwrap_or_default();
    let rep_loc = format!("{}:{}", rep.file, rep.start_line);
    let rep_loc = if pretty {
        // "  ── {loc} {name}  ★ representative" = loc + name + 24 fixed columns.
        style::truncate_left(
            &rep_loc,
            width.saturating_sub(rep.name.chars().count() + 24).max(16),
        )
    } else {
        rep_loc
    };
    out.push_str(&format!(
        "  {} {} {}  {}\n\n",
        style::dim("──"),
        style::dim(&rep_loc),
        style::bold(&rep.name),
        style::green("★ representative")
    ));

    for (i, m) in cluster.members.iter().enumerate() {
        if i == rep_i {
            continue;
        }
        let copy_src = read(i).unwrap_or_default();
        let loc = format!("{}:{}", m.file, m.start_line);
        let loc = if pretty {
            style::truncate_left(&loc, width.saturating_sub(20).max(16))
        } else {
            loc
        };
        out.push_str(&format!(
            "  {} {}  {}\n",
            style::dim("vs"),
            style::dim(&loc),
            style::yellow(&format!("{:.0}% similar", m.similarity * 100.0))
        ));
        if copy_src == rep_src {
            out.push_str(&format!(
                "     {}\n\n",
                style::dim("identical to representative")
            ));
            continue;
        }
        if pretty && width >= SIDE_BY_SIDE_MIN_WIDTH {
            render_diff_side_by_side(
                &mut out,
                &rep_src,
                &copy_src,
                rep.start_line,
                m.start_line,
                width,
            );
        } else {
            render_diff_unified(
                &mut out,
                &rep_src,
                &copy_src,
                rep.start_line,
                m.start_line,
                width,
            );
        }
        out.push('\n');
    }
    Ok(out)
}

/// `--full`: print each member's whole body, numbered and wrapped on a TTY,
/// plain `│ ` gutter when piped.
fn render_full(
    out: &mut String,
    output: &ScanOutput,
    internal: &Cluster,
    members: &[crate::report::MemberOut],
    pretty: bool,
    width: usize,
) {
    use crate::style;
    for (m_out, m) in members.iter().zip(&internal.members) {
        let f = &output.functions[m.func as usize];
        let marker_plain = if m_out.representative {
            "★ representative".to_string()
        } else {
            format!("{:.0}% similar", m_out.similarity * 100.0)
        };
        let marker = if m_out.representative {
            style::green(&marker_plain)
        } else {
            style::yellow(&marker_plain)
        };
        let mut loc = format!("{}:{}", m_out.file, m_out.start_line);
        if pretty {
            let budget = width
                .saturating_sub(8 + m_out.name.chars().count() + marker_plain.chars().count())
                .max(12);
            loc = style::truncate_left(&loc, budget);
        }
        out.push_str(&format!(
            "  {} {} {}  {}\n",
            style::dim("──"),
            style::dim(&loc),
            style::bold(&m_out.name),
            marker
        ));
        let path = &output.file_paths[f.file as usize];
        if let Ok(content) = std::fs::read_to_string(path) {
            let snippet = &content[f.start_byte as usize..f.end_byte as usize];
            if pretty {
                render_body(out, snippet, f.start_line, f.end_line, width);
            } else {
                for line in snippet.lines() {
                    out.push_str("  │ ");
                    out.push_str(line);
                    out.push('\n');
                }
            }
        }
        out.push('\n');
    }
}

/// Widest line number either side of the diff will print.
fn line_num_width(old_start: u32, old: &str, new_start: u32, new: &str) -> usize {
    let oe = old_start as usize + old.lines().count().saturating_sub(1);
    let ne = new_start as usize + new.lines().count().saturating_sub(1);
    oe.max(ne).max(1).to_string().len()
}

/// Visible width of a string in terminal columns.
fn vis_width(s: &str) -> usize {
    use unicode_width::UnicodeWidthChar;
    s.chars().map(|c| c.width().unwrap_or(0)).sum()
}

/// Collect a line's inline segments, dropping the trailing newline.
fn inline_segments<'a>(
    it: impl Iterator<Item = (bool, std::borrow::Cow<'a, str>)>,
) -> Vec<(bool, String)> {
    it.map(|(em, v)| (em, v.trim_end_matches(['\n', '\r']).to_string()))
        .collect()
}

/// Style a line's segments, truncating to `max_cols` columns with a dim `…`.
/// `base` styles ordinary text, `emph` the changed tokens. Returns the styled
/// string and the visible columns it occupies.
fn styled_truncated(
    segs: &[(bool, String)],
    base: StyleFn,
    emph: StyleFn,
    max_cols: usize,
) -> (String, usize) {
    use unicode_width::UnicodeWidthChar;
    let total: usize = segs.iter().map(|(_, v)| vis_width(v)).sum();
    let paint = |em: bool, t: &str| if em { emph(t) } else { base(t) };
    if total <= max_cols {
        let mut out = String::new();
        for (em, v) in segs {
            if !v.is_empty() {
                out.push_str(&paint(*em, v));
            }
        }
        return (out, total);
    }
    let cap = max_cols.saturating_sub(1);
    let mut out = String::new();
    let mut used = 0usize;
    for (em, v) in segs {
        if used >= cap {
            break;
        }
        let mut buf = String::new();
        for ch in v.chars() {
            let cw = ch.width().unwrap_or(0);
            if used + cw > cap {
                break;
            }
            buf.push(ch);
            used += cw;
        }
        if !buf.is_empty() {
            out.push_str(&paint(*em, &buf));
        }
    }
    out.push_str(&crate::style::dim("…"));
    (out, used + 1)
}

/// Unified diff: equal context dim, deletions `-` red, insertions `+` green,
/// changed tokens emphasized, unchanged runs collapsed. Long lines truncate.
fn render_diff_unified(
    out: &mut String,
    old: &str,
    new: &str,
    old_start: u32,
    new_start: u32,
    width: usize,
) {
    use crate::style;
    use similar::{ChangeTag, TextDiff};

    let diff = TextDiff::from_lines(old, new);
    let groups = diff.grouped_ops(DIFF_CONTEXT);
    let num_w = line_num_width(old_start, old, new_start, new);
    let budget = width.saturating_sub(num_w + 5).max(8);

    let mut prev_end = 0usize;
    for (gi, group) in groups.iter().enumerate() {
        let gap = group[0].old_range().start.saturating_sub(prev_end);
        if gi > 0 && gap > 0 {
            out.push_str(&format!(
                "  {}\n",
                style::dim(&format!("⋮ {gap} unchanged lines"))
            ));
        }
        for op in group {
            for change in diff.iter_inline_changes(op) {
                let (sign, lineno, base, emph): (&str, u32, StyleFn, StyleFn) = match change.tag() {
                    ChangeTag::Equal => (
                        " ",
                        old_start + change.old_index().unwrap_or(0) as u32,
                        style::dim,
                        style::dim,
                    ),
                    ChangeTag::Delete => (
                        "-",
                        old_start + change.old_index().unwrap_or(0) as u32,
                        style::red,
                        style::red_emph,
                    ),
                    ChangeTag::Insert => (
                        "+",
                        new_start + change.new_index().unwrap_or(0) as u32,
                        style::green,
                        style::green_emph,
                    ),
                };
                let segs = inline_segments(change.iter_strings_lossy());
                let (body, _) = styled_truncated(&segs, base, emph, budget);
                out.push_str(&format!(
                    "  {} {} {}\n",
                    style::dim(&format!("{lineno:>num_w$}")),
                    base(sign),
                    body
                ));
            }
        }
        prev_end = group[group.len() - 1].old_range().end;
    }
}

/// Side-by-side diff: representative on the left, the copy on the right, each in
/// its own numbered column truncated to half the width. Changed tokens are
/// emphasized; unchanged runs collapse.
fn render_diff_side_by_side(
    out: &mut String,
    old: &str,
    new: &str,
    old_start: u32,
    new_start: u32,
    width: usize,
) {
    use crate::style;
    use similar::{ChangeTag, TextDiff};

    let diff = TextDiff::from_lines(old, new);
    let groups = diff.grouped_ops(DIFF_CONTEXT);
    let num_w = line_num_width(old_start, old, new_start, new);
    // Row = "  " + (num + " " + col) + " " + (num + " " + col) = 2*num_w + 2*col + 5.
    let col = (width.saturating_sub(2 * num_w + 5) / 2).max(8);

    // One rendered half-row: a line number (or blanks) and styled, padded text.
    let half = |lineno: Option<u32>, body: &str, used: usize| -> String {
        let num = match lineno {
            Some(n) => style::dim(&format!("{n:>num_w$}")),
            None => " ".repeat(num_w),
        };
        let pad = " ".repeat(col.saturating_sub(used));
        format!("{num} {body}{pad}")
    };
    let blank_half = || format!("{} {}", " ".repeat(num_w), " ".repeat(col));

    let mut prev_end = 0usize;
    for (gi, group) in groups.iter().enumerate() {
        let gap = group[0].old_range().start.saturating_sub(prev_end);
        if gi > 0 && gap > 0 {
            out.push_str(&format!(
                "  {}\n",
                style::dim(&format!("⋮ {gap} unchanged lines"))
            ));
        }
        // Buffer deletions/insertions so a changed block pairs old↔new row-wise.
        let mut dels: Vec<(u32, String, usize)> = Vec::new();
        let mut inss: Vec<(u32, String, usize)> = Vec::new();
        let flush = |out: &mut String,
                     dels: &mut Vec<(u32, String, usize)>,
                     inss: &mut Vec<(u32, String, usize)>| {
            for i in 0..dels.len().max(inss.len()) {
                let left = match dels.get(i) {
                    Some((n, b, u)) => half(Some(*n), b, *u),
                    None => blank_half(),
                };
                let right = match inss.get(i) {
                    Some((n, b, u)) => half(Some(*n), b, *u),
                    None => blank_half(),
                };
                out.push_str(&format!("  {left} {right}\n"));
            }
            dels.clear();
            inss.clear();
        };

        for op in group {
            for change in diff.iter_inline_changes(op) {
                let segs = inline_segments(change.iter_strings_lossy());
                match change.tag() {
                    ChangeTag::Equal => {
                        flush(out, &mut dels, &mut inss);
                        let (b, u) = styled_truncated(&segs, style::dim, style::dim, col);
                        let oln = old_start + change.old_index().unwrap_or(0) as u32;
                        let nln = new_start + change.new_index().unwrap_or(0) as u32;
                        out.push_str(&format!(
                            "  {} {}\n",
                            half(Some(oln), &b, u),
                            half(Some(nln), &b, u)
                        ));
                    }
                    ChangeTag::Delete => {
                        let (b, u) = styled_truncated(&segs, style::red, style::red_emph, col);
                        dels.push((old_start + change.old_index().unwrap_or(0) as u32, b, u));
                    }
                    ChangeTag::Insert => {
                        let (b, u) = styled_truncated(&segs, style::green, style::green_emph, col);
                        inss.push((new_start + change.new_index().unwrap_or(0) as u32, b, u));
                    }
                }
            }
        }
        flush(out, &mut dels, &mut inss);
        prev_end = group[group.len() - 1].old_range().end;
    }
}

/// Render a function body for a TTY: a right-aligned line number, a dimmed
/// `│` gutter, and soft-wrapping so a long line never runs past `width`. The
/// wrapped remainder is indented under a dimmed `↳`.
fn render_body(out: &mut String, snippet: &str, start_line: u32, end_line: u32, width: usize) {
    use crate::style;

    let num_w = end_line.to_string().len();
    // "  " indent + number + " │ " on the first row; the continuation row swaps
    // the number for blanks and the leading space-pipe for "│ ↳ ".
    let first_budget = width.saturating_sub(2 + num_w + 3).max(8);
    let cont_budget = width.saturating_sub(2 + num_w + 5).max(8);

    for (i, raw) in snippet.lines().enumerate() {
        let lineno = start_line + i as u32;
        let line = expand_tabs(raw, 4);
        let segs = wrap_to_width(&line, first_budget, cont_budget);

        let gutter = style::dim(&format!("{lineno:>num_w$} │ "));
        out.push_str("  ");
        out.push_str(&gutter);
        out.push_str(segs.first().map_or("", |s| s.as_str()));
        out.push('\n');

        for seg in segs.iter().skip(1) {
            let cont = style::dim(&format!("{:>num_w$} │ ↳ ", ""));
            out.push_str("  ");
            out.push_str(&cont);
            out.push_str(seg);
            out.push('\n');
        }
    }
}

/// Expand tab characters to `n` spaces so wrapping and indentation line up.
fn expand_tabs(s: &str, n: usize) -> String {
    if s.contains('\t') {
        s.replace('\t', &" ".repeat(n))
    } else {
        s.to_string()
    }
}

/// Split a line into display-width-bounded segments: the first capped at
/// `first`, the rest at `cont`. Wraps on character boundaries (code, not prose),
/// measuring with Unicode display width.
fn wrap_to_width(s: &str, first: usize, cont: usize) -> Vec<String> {
    use unicode_width::UnicodeWidthChar;

    let mut segs = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    let mut budget = first;
    for ch in s.chars() {
        let cw = ch.width().unwrap_or(0);
        if cur_w + cw > budget && !cur.is_empty() {
            segs.push(std::mem::take(&mut cur));
            cur_w = 0;
            budget = cont;
        }
        cur.push(ch);
        cur_w += cw;
    }
    if !cur.is_empty() || segs.is_empty() {
        segs.push(cur);
    }
    segs
}

//! The slop score: the percentage of your code you could delete if every
//! duplicate cluster kept only one copy. That one sentence is the whole
//! formula — the representative copy is exempt, test-only clusters are
//! excluded by default, and nothing here guesses who (or what) wrote the
//! code.

use crate::cluster::Cluster;
use crate::config::TestPolicy;

pub struct Score {
    /// 0.0 - 100.0
    pub percent: f64,
    pub grade: char,
    pub deletable_lines: u64,
}

pub fn slop_score(clusters: &[Cluster], total_sig_lines: u64, tests: TestPolicy) -> Score {
    let deletable: u64 = clusters
        .iter()
        .filter(|c| !c.trait_impl_only)
        .filter(|c| tests == TestPolicy::Include || !c.test_only)
        .map(|c| c.deletable_lines as u64)
        .sum();
    let percent = if total_sig_lines == 0 {
        0.0
    } else {
        100.0 * deletable as f64 / total_sig_lines as f64
    };
    Score {
        percent,
        grade: grade(percent),
        deletable_lines: deletable,
    }
}

/// Grade buckets, calibrated against well-maintained OSS repos (see the
/// calibration table in the README).
pub fn grade(percent: f64) -> char {
    match percent {
        p if p < 3.0 => 'A',
        p if p < 6.0 => 'B',
        p if p < 10.0 => 'C',
        p if p < 15.0 => 'D',
        _ => 'F',
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cluster(deletable: u32, test_only: bool) -> Cluster {
        Cluster {
            members: vec![],
            deletable_lines: deletable,
            test_only,
            trait_impl_only: false,
        }
    }

    #[test]
    fn score_excludes_trait_impl_clusters_always() {
        let trait_cluster = Cluster {
            members: vec![],
            deletable_lines: 200,
            test_only: false,
            trait_impl_only: true,
        };
        let clusters = vec![cluster(50, false), trait_cluster];
        // Trait-impl clusters never count, even with --include-tests.
        let s = slop_score(&clusters, 1000, TestPolicy::FlagOnly);
        assert!((s.percent - 5.0).abs() < 1e-9);
        let s = slop_score(&clusters, 1000, TestPolicy::Include);
        assert!((s.percent - 5.0).abs() < 1e-9);
    }

    #[test]
    fn score_excludes_test_clusters_by_default() {
        let clusters = vec![cluster(50, false), cluster(100, true)];
        let s = slop_score(&clusters, 1000, TestPolicy::FlagOnly);
        assert!((s.percent - 5.0).abs() < 1e-9);
        assert_eq!(s.grade, 'B');

        let s = slop_score(&clusters, 1000, TestPolicy::Include);
        assert!((s.percent - 15.0).abs() < 1e-9);
        assert_eq!(s.grade, 'F');
    }

    #[test]
    fn empty_repo_scores_zero() {
        let s = slop_score(&[], 0, TestPolicy::FlagOnly);
        assert_eq!(s.percent, 0.0);
        assert_eq!(s.grade, 'A');
    }
}

//! Shared terminal styling. Color helpers degrade to plain text when stdout is
//! piped or NO_COLOR is set (owo-colors' supports-colors feature handles
//! detection), and width detection returns None off a TTY.

use owo_colors::{OwoColorize, Stream::Stdout};

pub fn dim(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.dimmed()).to_string()
}

pub fn bold(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.bold()).to_string()
}

pub fn green(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.green()).to_string()
}

pub fn yellow(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.yellow()).to_string()
}

pub fn red(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.red()).to_string()
}

/// A changed token on a deleted line: red background so it reads as a block,
/// delta-style. Keeps the terminal's default foreground for legibility.
pub fn red_emph(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.on_red()).to_string()
}

/// A changed token on an inserted line: green background.
pub fn green_emph(s: &str) -> String {
    s.if_supports_color(Stdout, |t| t.on_green()).to_string()
}

/// True when stdout is an interactive terminal. Drives the choice between the
/// pretty rendering and the plain, copy-paste-friendly one.
pub fn is_tty() -> bool {
    use std::io::IsTerminal;
    std::io::stdout().is_terminal()
}

/// Visible terminal width in columns, or `None` when the size can't be read
/// (piped, or a TTY that reports no window size). Callers on a TTY fall back to
/// a sensible default rather than refusing to wrap.
pub fn term_width() -> Option<usize> {
    use terminal_size::{Width, terminal_size};
    terminal_size().map(|(Width(w), _)| w as usize)
}

/// Left-truncate to `max` display columns, prefixing `…` so the informative
/// tail (a filename and line) survives.
pub fn truncate_left(s: &str, max: usize) -> String {
    let n = s.chars().count();
    if n <= max {
        s.to_string()
    } else {
        let cut: String = s.chars().skip(n - max + 1).collect();
        format!("…{cut}")
    }
}

//! "Reuse it like this" import suggestions for a duplicate finding.
//!
//! When `check` says a new function duplicates existing code, the obvious next
//! question is "so how do I call the original instead?". For languages where a
//! single import brings a top-level function into call-by-name scope, we can
//! answer that from the file path and the function name alone — no file reads,
//! no build graph. Where the answer would be a guess (methods that need their
//! enclosing type, header-based languages, package systems that import the
//! module rather than the symbol) we say nothing: a wrong hint is worse than
//! none, and dupehound already prints the definition's `file:line`.
//!
//! This is suggestion text only. dupehound never edits files.

use crate::lang::Lang;

/// The import/use line that pulls `original_name` (defined in `original_file`)
/// into `from_file` so the caller can delete the duplicate. `None` when the
/// language has no single-symbol import or the layout is too ambiguous to guess
/// safely.
pub fn import_suggestion(
    lang: Lang,
    original_file: &str,
    original_name: &str,
    from_file: &str,
) -> Option<String> {
    match lang {
        Lang::Rust => rust_use(original_file, original_name),
        Lang::Python => python_import(original_file, original_name),
        Lang::Typescript | Lang::Tsx | Lang::Javascript => {
            Some(ts_import(original_name, from_file, original_file))
        }
        // Method-based (Java, C#, Swift, C++), header-based (C), or
        // module-not-symbol imports (Go, Kotlin, PHP, Ruby): a single name is
        // not enough to name the import. Left for a follow-up that reads the
        // file's own package/namespace declaration.
        _ => None,
    }
}

/// `src/report/card.rs` + `render` -> `use crate::report::card::render;`.
/// `src/lib.rs` -> `use crate::render;`. Everything after the last `src`
/// component is treated as the module path (handles `mycrate/src/...` layouts).
fn rust_use(original_file: &str, name: &str) -> Option<String> {
    let stem = original_file.strip_suffix(".rs")?;
    let mut comps: Vec<&str> = stem.split('/').collect();
    if let Some(pos) = comps.iter().rposition(|c| *c == "src") {
        comps = comps.split_off(pos + 1);
    }
    // mod.rs / lib.rs / main.rs are the module itself, not a child named `mod`.
    if matches!(comps.last(), Some(&"mod" | &"lib" | &"main")) {
        comps.pop();
    }
    let path = comps.join("::");
    Some(if path.is_empty() {
        format!("use crate::{name};")
    } else {
        format!("use crate::{path}::{name};")
    })
}

/// `pkg/util/parse.py` + `parse_line` -> `from pkg.util.parse import parse_line`.
/// A leading `src/` (src-layout) and a trailing `__init__` are dropped.
fn python_import(original_file: &str, name: &str) -> Option<String> {
    let stem = original_file
        .strip_suffix(".py")
        .or_else(|| original_file.strip_suffix(".pyi"))?;
    let mut comps: Vec<&str> = stem.split('/').collect();
    if comps.first() == Some(&"src") {
        comps.remove(0);
    }
    if comps.last() == Some(&"__init__") {
        comps.pop();
    }
    let dotted = comps.join(".");
    if dotted.is_empty() {
        return None;
    }
    Some(format!("from {dotted} import {name}"))
}

/// `import { parseLine } from '<relative path>';`, where the path is resolved
/// from the importing file's directory to the original file, extension dropped.
fn ts_import(name: &str, from_file: &str, original_file: &str) -> String {
    let rel = relative_module_path(from_file, original_file);
    format!("import {{ {name} }} from '{rel}';")
}

/// POSIX relative path from `from_file`'s directory to `target_file`, with the
/// file extension removed and a `./` prefix forced when it would otherwise be
/// bare (ES modules require an explicit relative specifier).
fn relative_module_path(from_file: &str, target_file: &str) -> String {
    let from_dir: Vec<&str> = {
        let mut c: Vec<&str> = from_file.split('/').collect();
        c.pop(); // drop the filename
        c
    };
    let mut target: Vec<&str> = target_file.split('/').collect();
    if let Some(last) = target.last_mut() {
        if let Some((stem, _ext)) = last.rsplit_once('.') {
            *last = stem;
        }
    }

    // Walk off the shared prefix; the final target component (the stem) never
    // counts as shared so an import from a sibling still names the file.
    let mut i = 0;
    while i < from_dir.len() && i + 1 < target.len() && from_dir[i] == target[i] {
        i += 1;
    }

    let mut parts: Vec<&str> = vec![".."; from_dir.len() - i];
    parts.extend(&target[i..]);
    let joined = parts.join("/");
    if joined.starts_with("..") {
        joined
    } else {
        format!("./{joined}")
    }
}

